import SwiftUI
import Combine

// MARK: - Language system (v7.0)
//
// Five languages: English (US, the default and main
// language), Indonesian, Chinese (Simplified), Vietnamese,
// Russian. The choice lives in UserDefaults under
// "wt.language" ("en-US" / "id" / "zh-Hans" / "vi" / "ru").
//
// The English source string IS the lookup key: a missing
// translation falls back to English, so a string that was
// never translated still shows correctly. Views observe
// WTLangStore through the environment and call wtLang.tr(_:)
// for every user-facing string; when the language changes
// the whole app re-renders with no restart.
//
// EXCEPTION: the CacheExtra section is never looked up here
// — its editor, key names/values, "CacheExtra" labels and
// Reset Extra stay in English by design (see CacheExtraView).
// Proper nouns (WorkTweaks, Sandbox, MobileGestalt, bundle
// IDs, file paths, Log prefixes like [Battery]) are also
// never translated.

enum WTLanguage: String, CaseIterable, Identifiable {
    case enUS = "en-US"
    case id = "id"
    case zhHans = "zh-Hans"
    case vi = "vi"
    case ru = "ru"

    var id: String { rawValue }

    /// Name shown in the language picker, in its own language.
    var displayName: String {
        switch self {
        case .enUS: return "English (US)"
        case .id: return "Bahasa Indonesia"
        case .zhHans: return "中文 (简体)"
        case .vi: return "Tiếng Việt"
        case .ru: return "Русский"
        }
    }

    /// The "{Language} Version" line of the Sandbox header card.
    var versionLabel: String {
        switch self {
        case .enUS: return "English Version"
        case .id: return "Indonesia Version"
        case .zhHans: return "中文版本"
        case .vi: return "Phiên bản Tiếng Việt"
        case .ru: return "Русская версия"
        }
    }
}

final class WTLangStore: ObservableObject {
    static let shared = WTLangStore()
    static let defaultsKey = "wt.language"

    @Published var code: String {
        didSet {
            UserDefaults.standard.set(code, forKey: Self.defaultsKey)
        }
    }

    var language: WTLanguage { WTLanguage(rawValue: code) ?? .enUS }
    var theme: WTTheme { WTTheme.forLanguage(language) }

    private init() {
        self.code = UserDefaults.standard.string(forKey: Self.defaultsKey) ?? "en-US"
        // Re-apply the stored language's icon (no-op when it
        // is already active, so no alert on launch).
        WTAppIcon.apply(for: language)
    }

    func setLanguage(_ code: String) {
        guard WTLanguage(rawValue: code) != nil else { return }
        self.code = code
        // The icon color follows the language (iOS shows its
        // small system alert on the change).
        WTAppIcon.apply(for: language)
    }

    /// Translate an English source string. Missing keys fall
    /// back to the English source itself.
    func tr(_ key: String) -> String {
        if language == .enUS { return key }
        return WTStrings.table[code]?[key] ?? key
    }

    /// Translate a format string, keeping the %@ / %d
    /// placeholders in the same order in every language.
    func tr(_ key: String, _ args: CVarArg...) -> String {
        String(format: tr(key), arguments: args)
    }
}

/// Non-observed convenience for non-View code (log lines and
/// helpers). Views must use the environment object's tr(_:)
/// so they re-render when the language changes.
func L(_ key: String) -> String {
    WTLangStore.shared.tr(key)
}

