        "Disable Dynamic Island": "Nonaktifkan Dynamic Island",
        "Disable Dynamic Island System": "Nonaktifkan Sistem Dynamic Island",
        "Disables the Dynamic Island system completely — not just hiding it. Key: SBSuppressDynamicIslandCompletely in the managed com.apple.springboard.plist (set = 1).": "Menonaktifkan sistem Dynamic Island sepenuhnya — bukan hanya menyembunyikannya. Key: SBSuppressDynamicIslandCompletely di managed com.apple.springboard.plist (set = 1).",
        "Do not reboot! Your MobileGestalt.plist seems to be %@.": "Jangan reboot! MobileGestalt.plist Anda tampaknya %@.",
        "Done": "Selesai",
        "Download the WorkTweaks IPA from GitHub.": "Unduh IPA WorkTweaks dari GitHub.",
        "Download the latest WorkTweaks IPA from the GitHub Releases page.": "Unduh IPA WorkTweaks terbaru dari halaman GitHub Releases.",
        "Drag to move, pinch to zoom. The skin is saved at 1536×969.": "Seret untuk memindah, cubit untuk zoom. Skin disimpan pada ukuran 1536×969.",
        "Dual SIM: primary is the line used for data, secondary is the other line.": "Dual SIM: utama adalah jalur yang digunakan untuk data, sekunder adalah jalur lainnya.",
        "Dynamic Island": "Dynamic Island",
        "Each wallpaper in the package is copied into PosterBoard's data store under a fresh identifier, so it can never clash with an existing wallpaper. A respring is required before a new wallpaper appears in the gallery.": "Setiap wallpaper dalam paket disalin ke data store PosterBoard dengan identifier baru, sehingga tidak akan pernah bentrok dengan wallpaper yang sudah ada. Respring diperlukan sebelum wallpaper baru muncul di galeri.",
        "Edit": "Edit",
        "Edit Bytes": "Edit Byte",
        "Edit Cell": "Edit Sel",
        "Edit Package": "Edit Paket",
        "Edit Value": "Edit Nilai",
        "Edit in Theme Creator": "Edit di Theme Creator",
        "Edits replace byte values only — the file's length never changes. A backup of the original is saved before the first edit.": "Edit hanya mengganti nilai byte — panjang file tidak pernah berubah. Cadangan file asli disimpan sebelum edit pertama.",
        "Elements": "Elemen",
        "Eligibility": "Kelayakan",
        "Empty": "Kosong",
        "Enter this PIN in Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks.": "Masukkan PIN ini di Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks.",
        "Enumerating containers with pathleak — this can take a while.": "Mendaftar container dengan pathleak — ini bisa memakan waktu.",
        "Enumeration": "Enumerasi",
        "Error -1 means the signed app cannot access its App Group container. Diagnostics reads the groups from your signed provisioning profile and probes them all. If it reports no signed groups, the IPA was signed without an App Group and must be re-signed with one — no name typed here can fix that.": "Error -1 berarti app yang ditandatangani tidak bisa mengakses container App Group-nya. Diagnostik membaca grup dari provisioning profile yang ditandatangani dan memeriksa semuanya. Jika tidak ada grup bertanda tangan yang dilaporkan, IPA ditandatangani tanpa App Group dan harus ditandatangani ulang dengan App Group — nama apa pun yang diketik di sini tidak bisa memperbaikinya.",
        "Escape": "Escape",
        "Every menu that was applied, newest first. This is a history log — clearing it only clears the list, it does not undo anything.": "Setiap menu yang telah diterapkan, yang terbaru di atas. Ini adalah log riwayat — menghapusnya hanya menghapus daftar, tidak membatalkan apa pun.",
        "Exact path": "Path persis",
        "Expired %@ — reinstall the app first.": "Kedaluwarsa %@ — instal ulang aplikasi dulu.",
        "Expires soon — %@. Stage now, reinstall before it ends.": "Segera kedaluwarsa — %@. Stage sekarang, instal ulang sebelum berakhir.",
        "Export": "Ekspor",
        "Export Selected (%d)": "Ekspor yang Dipilih (%d)",
        "Export ZIP": "Ekspor ZIP",
        "Export the signed IPA and install it with ESign (or any IPA installer).": "Ekspor IPA yang sudah ditandatangani dan instal dengan ESign (atau installer IPA apa pun).",
        "Exported as .m4a files with their original titles, zipped to this app's Documents/VoiceMemosExports. The recordings database is only ever read — never written.": "Diekspor sebagai file .m4a dengan judul aslinya, di-zip ke Documents/VoiceMemosExports aplikasi ini. Database rekaman hanya dibaca — tidak pernah ditulis.",
        "Exporting…": "Mengekspor…",
        "Extra": "Ekstra",
        "Fake-Supervision Residue": "Sisa Supervisi Palsu",
        "Fast mode selected: only targets %@ with %@.": "Mode cepat dipilih: hanya menargetkan %@ dengan %@.",
        "File": "File",
