        "Import ZIP Backup…": "Impor Cadangan ZIP…",
        "Imported": "Diimpor",
        "In the Tweaks tab, Apple Intelligence section, turn on Apple Intelligence and Siri AI Cache Patch. The cache patch is the Filza line-104 edit (one CacheData byte, 0x00 to 0x02) — done here, no Filza needed.": "Di tab Tweaks, bagian Apple Intelligence, nyalakan Apple Intelligence dan Siri AI Cache Patch. Cache patch adalah edit Filza baris-104 (satu byte CacheData, 0x00 menjadi 0x02) — dilakukan di sini, tanpa Filza.",
        "Individual Keys": "Key Individual",
        "Install tab → Provisioning: fill in the fields below, tap Provision, and wait for \"profile OK\". Your Team ID is shown in the app's Certificates tab.": "Tab Install → Provisioning: isi kolom di bawah, ketuk Provision, dan tunggu \"profile OK\". Team ID Anda ditampilkan di tab Certificates aplikasi.",
        "Installation": "Instalasi",
        "Installed Profiles": "Profil Terinstal",
        "Installed any other way, the signed profile leaves the App Group out — and without it, the tweaks can't run. Tap Tutorials below for both step-by-step guides.": "Jika diinstal dengan cara lain, profil yang ditandatangani tidak menyertakan App Group — dan tanpanya, tweak tidak bisa berjalan. Ketuk Tutorials di bawah untuk kedua panduan langkah demi langkah.",
        "Installing into PosterBoard…": "Menginstal ke PosterBoard…",
        "Internal": "Internal",
        "Jetsam & Crash": "Jetsam & Crash",
        "Jetsam & Crash lists the reports iOS writes when it kills an app for memory (Jetsam, bug_type 298), when an app crashes (309), or on a watchdog / kernel panic (210). Open a report to see why it died, share the full file, or clean all reports to free space.": "Jetsam & Crash menampilkan laporan yang ditulis iOS saat mematikan aplikasi karena memori (Jetsam, bug_type 298), saat aplikasi crash (309), atau saat watchdog / kernel panic (210). Buka laporan untuk melihat penyebabnya, bagikan file lengkapnya, atau bersihkan semua laporan untuk mengosongkan ruang.",
