        "Name": "Nama",
        "Nested dictionaries, arrays and Data are shown read-only — the editor never rewrites a structure it cannot show.": "Dictionary, array, dan Data bersarang ditampilkan hanya-baca — editor tidak pernah menulis ulang struktur yang tidak bisa ditampilkannya.",
