        "No": "Tidak",
        "No AI cache targets were found.": "Tidak ada target cache AI ditemukan.",
        "No Cards Detected Yet": "Belum Ada Kartu Terdeteksi",
        "No Jailbreak": "Tanpa Jailbreak",
        "No ad targets found yet. Tap Scan above.": "Belum ada target iklan ditemukan. Ketuk Pindai di atas.",
        "No backed-up photos or videos yet. Use \"Backup Your Photos & Videos Here!\" first.": "Belum ada foto atau video yang dicadangkan. Gunakan \"Cadangkan Foto & Video Anda di Sini!\" terlebih dahulu.",
        "No containers were found, so there is nothing to clean.": "Tidak ada container yang ditemukan, jadi tidak ada yang perlu dibersihkan.",
        "No deploys yet. When a package is deployed, the files it replaced are backed up here with a receipt, ready to restore.": "Belum ada deploy. Saat paket di-deploy, file yang digantinya dicadangkan di sini beserta receipt, siap dipulihkan.",
        "No diagnostic reports found — nothing has been killed or crashed recently, or the reports were already cleaned.": "Tidak ada laporan diagnostik ditemukan — tidak ada yang dimatikan atau crash baru-baru ini, atau laporan sudah dibersihkan.",
        "No files yet.": "Belum ada file.",
        "No installable profile records were found in this directory.": "Tidak ada rekaman profil yang bisa diinstal ditemukan di direktori ini.",
        "No pairing file saved yet.": "Belum ada pairing file yang disimpan.",
        "No pairing file yet. Pair this iPhone first in Sandbox → Utilities → Get Pairing File — scanning and flashing need it.": "Belum ada pairing file. Pair iPhone ini dulu di Sandbox → Utilities → Get Pairing File — pemindaian dan flashing membutuhkannya.",
        "No recordings were found in the Voice Memos database.": "Tidak ada rekaman ditemukan di database Voice Memos.",
        "No regular files found in this container.": "Tidak ada file biasa yang ditemukan di container ini.",
        "No scan yet. The scan starts automatically; if it does not, open App Data once, or type the bundle ID by hand.": "Belum ada pemindaian. Pemindaian dimulai otomatis; jika tidak, buka Data Aplikasi sekali, atau ketik bundle ID secara manual.",
        "No skin — tap Set Skin below": "Tidak ada skin — ketuk Set Skin di bawah",
        "No snapshots yet. Apply some tweaks or tap Back Up Now.": "Belum ada snapshot. Terapkan beberapa tweak atau ketuk Cadangkan Sekarang.",
        "No stored packages yet. Build one with New Package, or import an existing .deploy / .zip / folder package to edit it here.": "Belum ada paket tersimpan. Buat satu dengan Paket Baru, atau impor paket .deploy / .zip / folder yang ada untuk mengeditnya di sini.",
        "No thermal events found in the powerlog.": "Tidak ada peristiwa termal ditemukan di powerlog.",
        "No third-party apps found.": "Tidak ada aplikasi pihak ketiga ditemukan.",
        "No tweaks match \"%@\".": "Tidak ada tweak yang cocok dengan \"%@\".",
        "No wallpapers imported yet. Wallpapers imported here are listed so you can remove them again — wallpapers added any other way are never touched.": "Belum ada wallpaper yang diimpor. Wallpaper yang diimpor di sini terdaftar agar Anda dapat menghapusnya lagi — wallpaper yang ditambahkan dengan cara lain tidak pernah disentuh.",
