        "Nothing staged yet.": "Belum ada yang di-stage.",
        "Nothing was written — the stored manifest is unchanged.": "Tidak ada yang ditulis — manifest tersimpan tidak berubah.",
        "Nothing was written.": "Tidak ada yang ditulis.",
        "Notice": "Pemberitahuan",
        "Numbers only.": "Hanya angka.",
        "OK": "OK",
        "Off": "Nonaktif",
