        "Old UI": "UI Lama",
        "On": "Aktif",
        "On a computer, download iLoader from iloader.app — the official site only — and open it.": "Di komputer, unduh iLoader dari iloader.app — hanya situs resmi — lalu buka.",
        "On in this backup": "Aktif di cadangan ini",
        "One of the destination paths is invalid.": "Salah satu path tujuan tidak valid.",
        "Only files under Library/Caches inside the listed targets are deleted. AI models are never touched, and caches regenerate when the apps run again.": "Hanya file di bawah Library/Caches di dalam target yang terdaftar yang dihapus. Model AI tidak pernah disentuh, dan cache dibuat ulang saat aplikasi berjalan lagi.",
        "Only spoof your device model if you want to download Apple Intelligence. This may break Face ID. If you decide to unspoof and want to keep Apple Intelligence, do NOT re-enter the Apple Intelligence & Siri menu in Settings.": "Spoof model perangkat Anda hanya jika Anda ingin mengunduh Apple Intelligence. Tindakan ini dapat merusak Face ID. Jika Anda memutuskan untuk berhenti spoof dan ingin tetap menggunakan Apple Intelligence, JANGAN masuk lagi ke menu Apple Intelligence & Siri di Settings.",
        "Only the listed .ips / .crash / .panic files under DiagnosticReports (and Retired) are ever deleted. The folders themselves are kept, and nothing else is touched.": "Hanya file .ips / .crash / .panic yang terdaftar di bawah DiagnosticReports (dan Retired) yang pernah dihapus. Foldernya sendiri tetap dipertahankan, dan tidak ada hal lain yang disentuh.",
        "Open App Data first so the container scan runs, then come back — or tap Rescan.": "Buka App Data dulu agar pemindaian container berjalan, lalu kembali — atau ketuk Rescan.",
        "Open Settings → Apple Intelligence & Siri and tap Join Waitlist. Wait about 15 minutes for it to be accepted.": "Buka Settings → Apple Intelligence & Siri lalu ketuk Join Waitlist. Tunggu sekitar 15 menit hingga diterima.",
        "Open Signed Apps and sign in with your Apple ID.": "Buka Signed Apps dan masuk dengan Apple ID Anda.",
        "Open Source": "Open Source",
        "Open Tutorials": "Buka Tutorial",
        "Open WorkTweaks and you're done.": "Buka WorkTweaks dan selesai.",
        "Open as Property List": "Buka sebagai Property List",
        "Open as SQLite Database": "Buka sebagai Database SQLite",
        "Open the Local Dev VPN app and connect. The tunnel shows as a utun interface on 10.7.x.x (gateway 10.7.0.1).": "Buka aplikasi Local Dev VPN dan hubungkan. Tunnel muncul sebagai interface utun di 10.7.x.x (gateway 10.7.0.1).",
        "Opening the configuration profiles…": "Membuka configuration profiles…",
        "Opening the database…": "Membuka database…",
        "Opens an empty editor; the file is created when you save.": "Membuka editor kosong; file dibuat saat Anda menyimpan.",
        "Opens the database as editable tables, with a backup taken before the first save. Close the owning app before editing.": "Membuka database sebagai tabel yang bisa diedit, dengan cadangan yang dibuat sebelum penyimpanan pertama. Tutup aplikasi pemiliknya sebelum mengedit.",
        "Opens the property list as an editable key/type/value table, with a backup taken before the first save.": "Membuka property list sebagai tabel kunci/tipe/nilai yang bisa diedit, dengan cadangan yang dibuat sebelum penyimpanan pertama.",
