        "Path Enumeration": "Enumerasi Path",
        "Paths must be relative, non-empty and contain no \"..\" component.": "Path harus relatif, tidak kosong, dan tidak mengandung komponen \"..\".",
        "Payload files are copied into the package. Add File accepts any file — a .plist is added as a payload, and a .zip is unpacked, each file inside becoming a payload with its destination defaulting to its path inside the archive. Destinations are relative paths only; absolute paths and \"..\" are rejected, exactly like an imported package.": "File payload disalin ke dalam paket. Tambah File menerima file apa pun — file .plist ditambahkan sebagai payload, dan file .zip dibuka, setiap file di dalamnya menjadi payload dengan tujuan default berupa path-nya di dalam arsip. Tujuan hanya boleh path relatif; path absolut dan \"..\" ditolak, sama seperti paket yang diimpor.",
        "Persist after reboot": "Tetap berlaku setelah reboot",
        "Photo Library": "Perpustakaan Foto",
        "Photo chosen — tap to change": "Foto dipilih — ketuk untuk mengubah",
        "Photos & Videos": "Foto & Video",
        "Pick Target App": "Pilih Aplikasi Target",
        "Pick an app": "Pilih aplikasi",
        "Pick an app to see its cache and clean it.": "Pilih aplikasi untuk melihat cache-nya dan membersihkannya.",
        "Pick from App Data scan…": "Pilih dari pemindaian Data Aplikasi…",
        "Pick the WorkTweaks IPA, set the Signing Bundle ID field to the same identifier, then tap Sign IPA.": "Pilih IPA WorkTweaks, atur kolom Signing Bundle ID ke identifier yang sama, lalu ketuk Sign IPA.",
        "Pick the photos and videos you want to keep, then Save. They are copied into the BackUP_Data folder inside the app. Optional — you can skip this.": "Pilih foto dan video yang ingin disimpan, lalu Simpan. File tersebut disalin ke folder BackUP_Data di dalam aplikasi. Opsional — Anda bisa melewatinya.",
        "Plays a soft sound when you tap menus and features. Respects the silent switch.": "Memutar suara lembut saat kamu membuka menu dan fitur. Hormati mode senyap.",
        "Please Install It the Right Way": "Harap Instal dengan Cara yang Benar",
        "PosterBoard Data": "Data PosterBoard",
        "PosterBoard Updated": "PosterBoard Diperbarui",
        "PosterBoard is unavailable": "PosterBoard tidak tersedia",
        "Power": "Daya",
        "Prepare Share": "Siapkan Bagikan",
        "Preparing the container scan…": "Menyiapkan pemindaian container…",
        "Preview (first 128 KB)": "Pratinjau (128 KB pertama)",
