        "Probing cache sizes…": "Memeriksa ukuran cache…",
        "Raw max capacity": "Kapasitas maks mentah",
        "Read": "Baca",
        "Read Powerlog": "Baca Powerlog",
        "Read complete%@%@.": "Pembacaan selesai%@%@.",
        "Read-only mode — the grant did not include write access, so Clean All is disabled.": "Mode hanya-baca — grant tidak menyertakan akses tulis, jadi Clean All dinonaktifkan.",
        "Read-only: the powerlog is cloned into this app's temp folder and inspected there. Nothing is ever written to the system database. Some iOS 26 firmware restricts the powerlog sandbox token; iOS 27 reads fully.": "Hanya-baca: powerlog di-clone ke folder temp aplikasi ini dan diperiksa di sana. Tidak ada yang pernah ditulis ke database sistem. Beberapa firmware iOS 26 membatasi token sandbox powerlog; iOS 27 membaca penuh.",
        "Reading the configuration profiles…": "Membaca configuration profile…",
        "Reading the property list…": "Membaca property list…",
        "Reading the recordings database…": "Membaca database rekaman…",
        "Reading video frames…": "Membaca frame video…",
        "Reading…": "Membaca…",
        "Rebooting now might cause a bootloop. Try pressing 'Revert Tweaks'.": "Reboot sekarang dapat menyebabkan bootloop. Coba tekan 'Kembalikan Tweaks'.",
        "Recent Requests": "Permintaan Terbaru",
        "Recent samples (%d)": "Sampel terbaru (%d)",
        "Reference": "Referensi",
        "Reference — APFS save-vault idea (clonefile staging, atomic swap with rollback).": "Referensi — ide save-vault APFS (clonefile staging, atomic swap dengan rollback).",
        "Reference — PosterBoard wallpaper format the maker was verified against.": "Referensi — format wallpaper PosterBoard yang dipakai untuk memverifikasi maker.",
        "Reference — Splash Ad Cache Lock mechanism (ad SDK cache lock, save vault, diagnostics, Wi-Fi file sharing, Voice Memos export, AI cache probes).": "Referensi — mekanisme Splash Ad Cache Lock (ad SDK cache lock, save vault, diagnostics, Wi-Fi file sharing, Voice Memos export, AI cache probes).",
        "Reference — app-data browsing and portable patches": "Referensi — penjelajahan app-data dan patch portabel",
        "Reference — cache data cleaner": "Referensi — pembersih cache data",
        "Reference — turn on new Siri AI (CacheData line edit + device spoof)": "Referensi — menyalakan Siri AI baru (edit baris CacheData + device spoof)",
        "Reference — video-to-wallpaper (CAML) builder used by the PosterBoard wallpaper maker.": "Referensi — builder video-ke-wallpaper (CAML) yang digunakan oleh PosterBoard wallpaper maker.",
        "Refresh": "Segarkan",
