        "Tweaks are locked": "Tweaks terkunci",
        "Two ways to get a pairing file: Pair This iPhone (iOS 27 only) shows a 6-digit PIN — approve it in Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks. Or import a pairing file (.plist) from your computer manually. The pairing file is saved in the app.": "Dua cara mendapatkan pairing file: Pair This iPhone (hanya iOS 27) menampilkan PIN 6 digit — setujui di Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks. Atau impor pairing file (.plist) dari komputer Anda secara manual. Pairing file disimpan di aplikasi.",
        "Type": "Jenis",
        "Type the region suffix as shown in Settings > General > About, e.g. PA/A or LL/A. It changes the Model Number suffix after Apply.": "Ketik akhiran region seperti yang ditampilkan di Settings > General > About, mis. PA/A atau LL/A. Akhiran ini mengubah akhiran Model Number setelah Apply.",
        "Type: %@ (%@). %@": "Tipe: %@ (%@). %@",
