        "Voltage": "Tegangan",
        "WARNING: These tweaks can break features on your device or softbrick it if misused. After Apply you choose Respring or Restart; Revert and Backup restores require a full device restart.": "PERINGATAN: Tweak ini dapat merusak fitur di perangkat Anda atau menyebabkan softbrick jika disalahgunakan. Setelah Apply, Anda memilih Respring atau Restart; pemulihan Revert dan Backup memerlukan restart perangkat penuh.",
        "Waiting for the App Data scan…": "Menunggu pemindaian App Data…",
        "Wallet Cards": "Kartu Wallet",
        "Wallpaper": "Wallpaper",
        "Wallpaper name": "Nama wallpaper",
        "Warning": "Peringatan",
        "Warning: raw byte edits have no structure validation — a wrong byte can corrupt this file or the owning app's data. A backup of the original is saved before the first edit.": "Peringatan: edit byte mentah tidak memiliki validasi struktur — satu byte yang salah dapat merusak file ini atau data aplikasi pemiliknya. Cadangan file asli disimpan sebelum edit pertama.",
        "WeChat accounts": "Akun WeChat",
        "Welcome to WorkTweaks": "Selamat Datang di WorkTweaks",
        "What this does": "Apa yang dilakukan fitur ini",
        "When enabled, MobileGestalt is written in-place on the same inode, which (hopefully) prevents iOS from regenerating the cache on reboot. Disable to use atomic file replacement instead.": "Saat diaktifkan, MobileGestalt ditulis di tempat pada inode yang sama, yang (semoga) mencegah iOS membuat ulang cache saat reboot. Nonaktifkan untuk menggunakan penggantian file atomik sebagai gantinya.",
        "Where it goes": "Ke mana perginya",
        "Whitelist": "Whitelist",
        "Whitelisted": "Di-whitelist",
        "Whole numbers only.": "Hanya bilangan bulat.",
        "Wi-Fi File Sharing": "Berbagi File Wi-Fi",
        "WorkTweaks is free software under the GNU Affero General Public License v3.0. The core (worse_query) is GPL-3.0, but the CacheExtra key knowledge from mond and the CacheData method from Nugget are AGPL-3.0 — GPLv3 code may be combined into an AGPLv3 work, and the AGPL terms then cover the combined work as a whole.": "WorkTweaks adalah perangkat lunak bebas di bawah GNU Affero General Public License v3.0. Inti (worse_query) berlisensi GPL-3.0, tetapi pengetahuan key CacheExtra dari mond dan metode CacheData dari Nugget berlisensi AGPL-3.0 — kode GPLv3 dapat digabungkan ke dalam karya AGPLv3, dan ketentuan AGPL kemudian mencakup keseluruhan karya gabungan.",
        "WorkTweaks must be installed with iLoader, or by signing the IPA with Signed Apps, so that its App Group works correctly.": "WorkTweaks harus diinstal dengan iLoader, atau dengan menandatangani IPA menggunakan Signed Apps, agar App Group-nya berfungsi dengan benar.",
        "WorkTweaks only works when its App Group is part of the signing profile. Guides A and B make sure that happens — pick the one that fits you. Guide C turns on the new Siri AI.": "WorkTweaks hanya berfungsi jika App Group-nya menjadi bagian dari signing profile. Panduan A dan B memastikan hal itu terjadi — pilih yang sesuai dengan Anda. Panduan C menyalakan Siri AI baru.",
        "WorkTweaks v3.0 only opens on the builds listed above: the app checks your device's build at launch, and any other build gets the \"not supported\" screen instead of the app. On iOS 18 and iOS 26, only App Data and Airlift are supported (partial support). Developed and tested on iOS 27.0.1 (24A446).": "WorkTweaks v3.0 hanya terbuka pada build yang tercantum di atas: aplikasi memeriksa build perangkat Anda saat peluncuran, dan build lain akan mendapatkan layar \"not supported\" sebagai gantinya. Di iOS 18 dan iOS 26, hanya App Data dan Airlift yang didukung (dukungan parsial). Dikembangkan dan diuji di iOS 27.0.1 (24A446).",
        "Works on iOS 18.0 – 27.2 beta 2 (iOS 27.2 beta 3 and later patched the exploit).": "Berfungsi di iOS 18.0 – 27.2 beta 2 (iOS 27.2 beta 3 dan yang lebih baru telah menambal exploit ini).",
        "Write Method": "Metode Penulisan",
        "Write access available — Clean All can delete the listed reports.": "Akses tulis tersedia — Clean All bisa menghapus laporan yang terdaftar.",
        "Writes SharedDeviceConfiguration.plist in place, keeping every other key in the file. SpringBoard reads the file when it starts, so a respring or restart is needed to see the change.": "Menulis SharedDeviceConfiguration.plist di tempatnya, menjaga setiap key lain dalam file. SpringBoard membaca file saat dimulai, jadi respring atau restart diperlukan untuk melihat perubahan.",
        "Writing or verifying the file failed — the details are in the Log.": "Gagal menulis atau memverifikasi file — detailnya ada di Log.",
        "Writing the file failed — the details are in the Log.": "Gagal menulis file — detailnya ada di Log.",
        "Writing the footnote failed — the details are in the Log.": "Penulisan footnote gagal — detailnya ada di Log.",
        "Yes": "Ya",
        "You can add multiple hashes at once — separate them with spaces, commas, or newlines.": "Anda dapat menambahkan beberapa hash sekaligus — pisahkan dengan spasi, koma, atau baris baru.",
        "Your All BackUP Files Here!": "Semua File BackUP Anda di Sini!",
        "Your device is running **%@**. WorkTweaks v2.0 only runs on the builds listed below, so the app can't open on this version.": "Perangkat Anda menjalankan **%@**. WorkTweaks v2.0 hanya berjalan pada build yang tercantum di bawah, jadi aplikasi tidak dapat dibuka pada versi ini.",
        "ZIP backup saved: %@. Share it to Files before you uninstall anything.": "Cadangan ZIP tersimpan: %@. Bagikan ke Files sebelum kamu meng-uninstall apa pun.",
        "empty": "kosong",
