        "iPadOS Features": "Fitur iPadOS",
        "invalid": "tidak valid",
        "the CacheExtra key knowledge behind the tweak catalog": "pengetahuan key CacheExtra di balik katalog tweak",
        "the file-based CacheData method (iPadOS Mode)": "metode CacheData berbasis file (iPadOS Mode)",
        "the package": "paket",
        "the respring technique (jailbreak.party)": "teknik respring (jailbreak.party)",
        "true or false.": "true atau false.",
        "v3.0 checks your device's build at launch and only opens on the supported builds. The full version & build list lives in License & Credits.": "v3.0 memeriksa build perangkat Anda saat peluncuran dan hanya terbuka pada build yang didukung. Daftar lengkap versi & build ada di License & Credits.",
        "worse_query — the core system (sandbox escape)": "worse_query — sistem inti (sandbox escape)",
