        "Battery & Thermal reads the system powerlog database: battery level, true health (raw max vs design capacity), cycle count, cell temperature, and thermal history. Values come from the latest samples in the log, newest first.": "Battery & Thermal 读取系统 powerlog 数据库：电池电量、真实健康度（原始最大容量 vs 设计容量）、循环次数、电芯温度和散热历史。数值取自日志中的最新样本，按最新优先排序。",
