        "Before anything is written, every file that already exists is backed up (see Deploy History). Existing files are then replaced in place; new files are created.": "在写入任何内容之前，所有已存在的文件都会先备份（见部署历史）。现有文件随后会被原地替换；新文件会被创建。",
        "Blocked — pairing / VPN not ready": "已阻止——配对 / VPN 未就绪",
        "Both need a pairing file first: Sandbox → Utilities → Get Pairing File. A loopback VPN (Local Dev VPN) is strongly recommended while flashing.": "两者都需要先准备配对文件：Sandbox → Utilities → Get Pairing File。刷入时强烈建议使用环回 VPN (Local Dev VPN)。",
        "Browse Files": "浏览文件",
        "Build": "构建",
        "Build & Install Wallpaper": "构建并安装壁纸",
        "Building still wallpaper…": "正在构建静态壁纸…",
        "Builds a PosterBoard wallpaper on-device from your photo or video — the same descriptor format as an imported .tendies package, installed and listed exactly like one.": "在设备上根据您的照片或视频构建 PosterBoard 壁纸——与导入的 .tendies 软件包使用相同的描述符格式，安装和列出方式完全相同。",
        "Built on the worse_query core system by ForceQuit OS, with CacheExtra key knowledge from mond by rooootdev (AGPL-3.0).": "基于 ForceQuit OS 的 worse_query 核心系统构建，CacheExtra 密钥知识来自 rooootdev 的 mond (AGPL-3.0)。",
