        "Cache Locations": "缓存位置",
        "Cache lives in two places inside an app's data container: Library/Caches and tmp. Only the contents of those two folders are deleted — the folders themselves stay, and Documents and the rest of Library are never touched.": "缓存位于应用数据容器内的两个位置：Library/Caches 和 tmp。仅删除这两个文件夹的内容——文件夹本身会保留，Documents 和 Library 的其余部分绝不会被触碰。",
