        "Change .passthm…": "更改 .passthm…",
        "Change the carrier name, network label and signal bars. iOS 27 only. A separate system from the Tweaks tab. LiveContainer is not recommended for this — use a direct install (Signed Apps) instead.": "更改运营商名称、网络标签和信号格。仅限 iOS 27。这是一个与 Tweaks 标签页独立的系统。不建议为此使用 LiveContainer——请改用直接安装（Signed Apps）。",
