        "Connect your iPhone by USB, then sign in with your Apple ID in iLoader.": "通过 USB 连接您的 iPhone，然后在 iLoader 中使用您的 Apple ID 登录。",
        "Connect your iPhone to power, connect to Wi-Fi, and leave the Settings → General → iPhone Storage tab open for about 1 hour while the model downloads.": "将您的 iPhone 连接电源、连接 Wi-Fi，并让 Settings → General → iPhone Storage 标签页保持打开约 1 小时，等待模型下载。",
