        "Disable Dynamic Island System": "禁用 Dynamic Island 系统",
        "Disables the Dynamic Island system completely — not just hiding it. Key: SBSuppressDynamicIslandCompletely in the managed com.apple.springboard.plist (set = 1).": "完全禁用 Dynamic Island 系统——不只是隐藏它。Key：托管的 com.apple.springboard.plist 中的 SBSuppressDynamicIslandCompletely（设为 1）。",
        "Do not reboot! Your MobileGestalt.plist seems to be %@.": "请勿重启！您的 MobileGestalt.plist 似乎 %@。",
        "Done": "完成",
        "Download the WorkTweaks IPA from GitHub.": "从 GitHub 下载 WorkTweaks IPA。",
        "Download the latest WorkTweaks IPA from the GitHub Releases page.": "从 GitHub Releases 页面下载最新的 WorkTweaks IPA。",
        "Drag to move, pinch to zoom. The skin is saved at 1536×969.": "拖动以移动，双指捏合以缩放。皮肤将以 1536×969 保存。",
        "Dual SIM: primary is the line used for data, secondary is the other line.": "双卡：主卡是用于数据的线路，副卡是另一条线路。",
        "Dynamic Island": "Dynamic Island",
        "Each wallpaper in the package is copied into PosterBoard's data store under a fresh identifier, so it can never clash with an existing wallpaper. A respring is required before a new wallpaper appears in the gallery.": "软件包中的每张壁纸都会以新的标识符复制到 PosterBoard 数据存储中，因此绝不会与现有壁纸冲突。新壁纸出现在图库之前需要执行一次 respring。",
