        "Edit Value": "编辑值",
        "Edit in Theme Creator": "在 Theme Creator 中编辑",
        "Edits replace byte values only — the file's length never changes. A backup of the original is saved before the first edit.": "编辑仅替换字节值——文件长度永远不会改变。在首次编辑前会保存原始文件的备份。",
        "Elements": "元素",
        "Eligibility": "资格",
        "Empty": "空",
        "Enter this PIN in Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks.": "在 Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks 中输入此 PIN。",
        "Enumerating containers with pathleak — this can take a while.": "正在使用 pathleak 枚举容器——这可能需要一些时间。",
        "Enumeration": "枚举",
        "Error -1 means the signed app cannot access its App Group container. Diagnostics reads the groups from your signed provisioning profile and probes them all. If it reports no signed groups, the IPA was signed without an App Group and must be re-signed with one — no name typed here can fix that.": "错误 -1 表示已签名的应用无法访问其 App Group 容器。诊断会读取已签名描述文件中的群组并逐一探测。如果未报告任何已签名的群组，则 IPA 签名时未包含 App Group，必须重新签名——在此输入任何名称都无法修复。",
        "Escape": "逃逸",
        "Every menu that was applied, newest first. This is a history log — clearing it only clears the list, it does not undo anything.": "所有已应用的菜单，最新在前。这是一份历史记录——清除它只会清除列表，不会撤销任何内容。",
        "Exact path": "精确路径",
        "Expired %@ — reinstall the app first.": "已于 %@ 过期——请先重装应用。",
        "Expires soon — %@. Stage now, reinstall before it ends.": "即将过期——%@。请立即暂存，并在过期前重装。",
        "Export": "导出",
        "Export Selected (%d)": "导出所选 (%d)",
        "Export ZIP": "导出 ZIP",
        "Export the signed IPA and install it with ESign (or any IPA installer).": "导出已签名的 IPA，并使用 ESign（或任何 IPA 安装器）安装它。",
        "Exported as .m4a files with their original titles, zipped to this app's Documents/VoiceMemosExports. The recordings database is only ever read — never written.": "以原始标题导出为 .m4a 文件，打包到此应用的 Documents/VoiceMemosExports。录音数据库仅供读取——从不写入。",
        "Exporting…": "正在导出…",
