        "Footnote Updated": "脚注已更新",
        "Footnote text": "脚注文本",
        "For AppGroup scope, the target is the App Group identifier (for example group.com.example) — type it here.": "对于 AppGroup 范围，目标是 App Group 标识符（例如 group.com.example）——请在此输入。",
        "Force-close the Wallet app from the App Switcher after flashing to see the new card art.": "刷入后，请从 App Switcher 中强制关闭 Wallet 应用，以查看新的卡面。",
        "Forces the label shown (5G, 5G+, 5G UC, LTE, …). Limited — the label is display-only.": "强制显示标签（5G、5G+、5G UC、LTE 等）。有限制——该标签仅用于显示。",
        "Free Apple ID installs expire after about 7 days — reinstall with iLoader to renew.": "免费 Apple ID 安装约 7 天后过期——请使用 iLoader 重新安装以续期。",
        "Freed %@": "已释放 %@",
