        "Get Pairing File + Local Dev VPN tunnel — the on-device pairing Airlift uses to reach the device.": "Get Pairing File + Local Dev VPN 隧道——Airlift 用于连接设备的本机配对。",
        "Get Pairing File + VPN Status": "获取配对文件 + VPN 状态",
        "Get Started": "开始使用",
        "Go to Sandbox Tab": "前往 Sandbox 标签页",
        "Go to the Apply/Revert section and tap Apply, then Respring. When the respring finishes, restart your iPhone.": "前往 Apply/Revert 部分，点击 Apply，然后 Respring。Respring 完成后，重启您的 iPhone。",
        "Go to the Sandbox tab and turn on Start Tweaks Feature to unlock the Tweaks tab.": "前往 Sandbox 标签页并开启 Start Tweaks Feature 以解锁 Tweaks 标签页。",
