        "ISO date (e.g. 2026-11-24T15:30:00Z) or yyyy-MM-dd HH:mm:ss.": "ISO 日期（例如 2026-11-24T15:30:00Z）或 yyyy-MM-dd HH:mm:ss。",
        "Identifiers from the App Data container scan — the same list Deploy resolves Application targets against.": "来自应用数据容器扫描的标识符——Deploy 解析 Application 目标时使用的同一列表。",
        "Idle": "空闲",
        "If iOS asks, enable Developer Mode (Settings → Privacy & Security → Developer Mode) and trust the developer profile.": "如果 iOS 提示，请启用 Developer Mode（Settings → Privacy & Security → Developer Mode）并信任开发者描述文件。",
        "If you update or downgrade to a supported build, WorkTweaks will open normally.": "如果您更新或降级到受支持的构建，WorkTweaks 将正常打开。",
