        "Paths must be relative, non-empty and contain no \"..\" component.": "路径必须为相对路径、非空且不包含“..”部分。",
        "Payload files are copied into the package. Add File accepts any file — a .plist is added as a payload, and a .zip is unpacked, each file inside becoming a payload with its destination defaulting to its path inside the archive. Destinations are relative paths only; absolute paths and \"..\" are rejected, exactly like an imported package.": "载荷文件会被复制到安装包中。“添加文件”接受任何文件——.plist 文件作为载荷添加，.zip 文件会被解包，其中每个文件都成为一个载荷，其目标默认为它在压缩包内的路径。目标仅限相对路径；绝对路径和“..”会被拒绝，与导入的安装包完全相同。",
