        "Read-only mode — the grant did not include write access, so Clean All is disabled.": "只读模式——授权未包含写入权限，因此 Clean All 已禁用。",
        "Read-only: the powerlog is cloned into this app's temp folder and inspected there. Nothing is ever written to the system database. Some iOS 26 firmware restricts the powerlog sandbox token; iOS 27 reads fully.": "只读：powerlog 会被克隆到此应用的临时文件夹中并在其中检查。绝不会向系统数据库写入任何内容。部分 iOS 26 固件会限制 powerlog 沙盒令牌；iOS 27 可完整读取。",
