        "Reference — PosterBoard wallpaper format the maker was verified against.": "参考——用于验证制作器的 PosterBoard 壁纸格式。",
        "Reference — Splash Ad Cache Lock mechanism (ad SDK cache lock, save vault, diagnostics, Wi-Fi file sharing, Voice Memos export, AI cache probes).": "参考——Splash Ad Cache Lock 机制（广告 SDK 缓存锁定、保存库、诊断、Wi-Fi 文件共享、Voice Memos 导出、AI 缓存探测）。",
