        "Restore a ZIP backup": "恢复 ZIP 备份",
        "Restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "恢复更改只有在设备完全重新启动后才会生效——仅重新启动 SpringBoard 是不够的。选择“稍后”只是推迟它；更改将一直处于待处理状态，直到您重新启动。",
        "Restore into…": "恢复到…",
        "Restore swaps the staged copy into the app's current container and rolls back if anything fails. Release a snapshot only after you verified the restore in the app.": "恢复会将暂存副本换入应用当前容器，若有任何失败则回滚。只有在应用中验证恢复无误后，才释放快照。",
        "Restore the backup?": "要恢复备份吗？",
