        "Battery & Thermal": "Pin & Nhiệt",
        "Battery & Thermal reads the system powerlog database: battery level, true health (raw max vs design capacity), cycle count, cell temperature, and thermal history. Values come from the latest samples in the log, newest first.": "Battery & Thermal đọc cơ sở dữ liệu powerlog hệ thống: mức pin, sức khỏe thực (raw max so với dung lượng thiết kế), số chu kỳ, nhiệt độ cell và lịch sử nhiệt. Giá trị lấy từ các mẫu mới nhất trong nhật ký, mới nhất trước.",
        "Battery Percentage": "Phần trăm pin",
        "Before anything is written, every file that already exists is backed up (see Deploy History). Existing files are then replaced in place; new files are created.": "Trước khi ghi bất cứ thứ gì, mọi tệp đã tồn tại đều được sao lưu (xem Lịch sử triển khai). Các tệp hiện có sau đó được thay thế tại chỗ; các tệp mới được tạo.",
        "Blocked — pairing / VPN not ready": "Bị chặn — ghép nối / VPN chưa sẵn sàng",
        "Both need a pairing file first: Sandbox → Utilities → Get Pairing File. A loopback VPN (Local Dev VPN) is strongly recommended while flashing.": "Cả hai đều cần tệp ghép nối trước: Sandbox → Utilities → Get Pairing File. Nên dùng VPN loopback (Local Dev VPN) khi flash.",
