        "Certificate": "Chứng chỉ",
        "Certificates tab: create your certificate if needed. A free team can hold only one active development certificate — if creation fails with error 7460, revoke an old unused certificate there first.": "Tab Certificates: tạo chứng chỉ của bạn nếu cần. Nhóm miễn phí chỉ được giữ một chứng chỉ phát triển đang hoạt động — nếu tạo thất bại với lỗi 7460, hãy thu hồi một chứng chỉ cũ không dùng ở đó trước.",
        "Change .passthm…": "Đổi .passthm…",
