        "Disables the Dynamic Island system completely — not just hiding it. Key: SBSuppressDynamicIslandCompletely in the managed com.apple.springboard.plist (set = 1).": "Tắt hoàn toàn hệ thống Dynamic Island — không chỉ ẩn nó. Key: SBSuppressDynamicIslandCompletely trong com.apple.springboard.plist được quản lý (đặt = 1).",
        "Do not reboot! Your MobileGestalt.plist seems to be %@.": "Đừng khởi động lại! MobileGestalt.plist của bạn có vẻ %@.",
        "Done": "Xong",
        "Download the WorkTweaks IPA from GitHub.": "Tải IPA WorkTweaks từ GitHub.",
        "Download the latest WorkTweaks IPA from the GitHub Releases page.": "Tải IPA WorkTweaks mới nhất từ trang GitHub Releases.",
        "Drag to move, pinch to zoom. The skin is saved at 1536×969.": "Kéo để di chuyển, chụm để phóng to. Skin được lưu ở kích thước 1536×969.",
        "Dual SIM: primary is the line used for data, secondary is the other line.": "Dual SIM: chính là đường dây dùng cho dữ liệu, phụ là đường dây còn lại.",
        "Dynamic Island": "Dynamic Island",
        "Each wallpaper in the package is copied into PosterBoard's data store under a fresh identifier, so it can never clash with an existing wallpaper. A respring is required before a new wallpaper appears in the gallery.": "Mỗi hình nền trong gói được sao chép vào kho dữ liệu của PosterBoard với một định danh mới, nên không bao giờ xung đột với hình nền hiện có. Cần respring trước khi hình nền mới xuất hiện trong thư viện.",
        "Edit": "Sửa",
