        "History": "Lịch sử",
        "ISO date (e.g. 2026-11-24T15:30:00Z) or yyyy-MM-dd HH:mm:ss.": "Ngày ISO (vd: 2026-11-24T15:30:00Z) hoặc yyyy-MM-dd HH:mm:ss.",
        "Identifiers from the App Data container scan — the same list Deploy resolves Application targets against.": "Các mã định danh từ lần quét container Dữ liệu ứng dụng — cùng danh sách mà Deploy dùng để xác định các đích Application.",
        "Idle": "Nhàn rỗi",
        "If iOS asks, enable Developer Mode (Settings → Privacy & Security → Developer Mode) and trust the developer profile.": "Nếu iOS yêu cầu, hãy bật Developer Mode (Settings → Privacy & Security → Developer Mode) và tin cậy hồ sơ nhà phát triển.",
        "If you update or downgrade to a supported build, WorkTweaks will open normally.": "Nếu bạn cập nhật hoặc hạ cấp xuống bản dựng được hỗ trợ, WorkTweaks sẽ mở bình thường.",
