        "Never share your certificate .p12 file with anyone — it contains your private signing key.": "Không bao giờ chia sẻ tệp chứng chỉ .p12 của bạn với bất kỳ ai — nó chứa khóa ký riêng tư của bạn.",
        "New Package": "Gói mới",
        "New Row": "Hàng mới",
        "New UI": "Giao diện mới",
        "No": "Không",
        "No AI cache targets were found.": "Không tìm thấy mục tiêu bộ nhớ đệm AI nào.",
        "No Cards Detected Yet": "Chưa phát hiện thẻ nào",
        "No Jailbreak": "Không cần Jailbreak",
        "No ad targets found yet. Tap Scan above.": "Chưa tìm thấy mục tiêu quảng cáo nào. Chạm Quét ở trên.",
        "No backed-up photos or videos yet. Use \"Backup Your Photos & Videos Here!\" first.": "Chưa có ảnh hoặc video nào được sao lưu. Hãy dùng \"Sao lưu ảnh & video của bạn tại đây!\" trước.",
        "No containers were found, so there is nothing to clean.": "Không tìm thấy container nào nên không có gì để dọn.",
        "No deploys yet. When a package is deployed, the files it replaced are backed up here with a receipt, ready to restore.": "Chưa có lần triển khai nào. Khi một gói được triển khai, các tệp mà nó thay thế sẽ được sao lưu tại đây kèm biên nhận, sẵn sàng khôi phục.",
        "No diagnostic reports found — nothing has been killed or crashed recently, or the reports were already cleaned.": "Không tìm thấy báo cáo chẩn đoán nào — gần đây không có gì bị tắt hay crash, hoặc các báo cáo đã được dọn rồi.",
        "No files yet.": "Chưa có tệp nào.",
        "No installable profile records were found in this directory.": "Không tìm thấy bản ghi hồ sơ nào có thể cài đặt trong thư mục này.",
        "No pairing file saved yet.": "Chưa lưu tệp ghép nối nào.",
        "No pairing file yet. Pair this iPhone first in Sandbox → Utilities → Get Pairing File — scanning and flashing need it.": "Chưa có tệp ghép nối. Hãy ghép nối iPhone này trước trong Sandbox → Utilities → Get Pairing File — việc quét và flash đều cần nó.",
        "No recordings were found in the Voice Memos database.": "Không tìm thấy bản ghi nào trong cơ sở dữ liệu Voice Memos.",
        "No regular files found in this container.": "Không tìm thấy tệp thông thường nào trong container này.",
        "No scan yet. The scan starts automatically; if it does not, open App Data once, or type the bundle ID by hand.": "Chưa quét. Quá trình quét tự động bắt đầu; nếu không, hãy mở Dữ liệu ứng dụng một lần, hoặc nhập bundle ID bằng tay.",
        "No skin — tap Set Skin below": "Chưa có skin — nhấn Set Skin bên dưới",
        "No snapshots yet. Apply some tweaks or tap Back Up Now.": "Chưa có ảnh chụp nhanh nào. Hãy áp dụng một vài tinh chỉnh hoặc chạm vào Sao lưu ngay.",
        "No stored packages yet. Build one with New Package, or import an existing .deploy / .zip / folder package to edit it here.": "Chưa có gói nào được lưu. Hãy tạo một gói bằng Gói mới, hoặc nhập gói .deploy / .zip / thư mục hiện có để chỉnh sửa tại đây.",
        "No thermal events found in the powerlog.": "Không tìm thấy sự kiện nhiệt nào trong powerlog.",
        "No third-party apps found.": "Không tìm thấy ứng dụng bên thứ ba nào.",
        "No tweaks match \"%@\".": "Không có tinh chỉnh nào khớp với \"%@\".",
        "No wallpapers imported yet. Wallpapers imported here are listed so you can remove them again — wallpapers added any other way are never touched.": "Chưa nhập hình nền nào. Các hình nền được nhập tại đây sẽ được liệt kê để bạn có thể xóa lại — các hình nền được thêm bằng cách khác không bao giờ bị động đến.",
        "Nominal capacity": "Dung lượng danh định",
