        "Old UI": "Giao diện cũ",
        "On": "Bật",
        "On a computer, download iLoader from iloader.app — the official site only — and open it.": "Trên máy tính, tải iLoader từ iloader.app — chỉ trang web chính thức — rồi mở nó.",
        "On in this backup": "Đang bật trong bản sao lưu này",
        "One of the destination paths is invalid.": "Một trong các đường dẫn đích không hợp lệ.",
        "Only files under Library/Caches inside the listed targets are deleted. AI models are never touched, and caches regenerate when the apps run again.": "Chỉ các tệp trong Library/Caches bên trong các mục tiêu được liệt kê mới bị xóa. Các mô hình AI không bao giờ bị chạm tới và bộ nhớ đệm sẽ được tạo lại khi ứng dụng chạy lại.",
        "Only spoof your device model if you want to download Apple Intelligence. This may break Face ID. If you decide to unspoof and want to keep Apple Intelligence, do NOT re-enter the Apple Intelligence & Siri menu in Settings.": "Chỉ giả mạo model thiết bị nếu bạn muốn tải xuống Apple Intelligence. Việc này có thể làm hỏng Face ID. Nếu bạn quyết định ngừng giả mạo và muốn giữ Apple Intelligence, KHÔNG vào lại menu Apple Intelligence & Siri trong Settings.",
        "Only the listed .ips / .crash / .panic files under DiagnosticReports (and Retired) are ever deleted. The folders themselves are kept, and nothing else is touched.": "Chỉ các tệp .ips / .crash / .panic được liệt kê trong DiagnosticReports (và Retired) mới bị xóa. Bản thân các thư mục được giữ lại và không chạm vào bất cứ thứ gì khác.",
        "Open App Data first so the container scan runs, then come back — or tap Rescan.": "Hãy mở App Data trước để quá trình quét vùng chứa chạy, rồi quay lại — hoặc chạm Rescan.",
        "Open Settings → Apple Intelligence & Siri and tap Join Waitlist. Wait about 15 minutes for it to be accepted.": "Mở Settings → Apple Intelligence & Siri rồi nhấn Join Waitlist. Chờ khoảng 15 phút để được chấp nhận.",
        "Open Signed Apps and sign in with your Apple ID.": "Mở Signed Apps rồi đăng nhập bằng Apple ID của bạn.",
        "Open Source": "Mã nguồn mở",
        "Open Tutorials": "Mở hướng dẫn",
        "Open WorkTweaks and you're done.": "Mở WorkTweaks là xong.",
        "Open as Property List": "Mở dưới dạng Property List",
        "Open as SQLite Database": "Mở dưới dạng cơ sở dữ liệu SQLite",
        "Open the Local Dev VPN app and connect. The tunnel shows as a utun interface on 10.7.x.x (gateway 10.7.0.1).": "Mở ứng dụng Local Dev VPN và kết nối. Đường hầm hiển thị dưới dạng giao diện utun trên 10.7.x.x (gateway 10.7.0.1).",
        "Opening the configuration profiles…": "Đang mở các hồ sơ cấu hình…",
        "Opening the database…": "Đang mở cơ sở dữ liệu…",
        "Opens an empty editor; the file is created when you save.": "Mở một trình chỉnh sửa trống; tệp sẽ được tạo khi bạn lưu.",
        "Opens the database as editable tables, with a backup taken before the first save. Close the owning app before editing.": "Mở cơ sở dữ liệu dưới dạng các bảng có thể chỉnh sửa, với bản sao lưu được tạo trước lần lưu đầu tiên. Hãy đóng ứng dụng sở hữu trước khi chỉnh sửa.",
        "Opens the property list as an editable key/type/value table, with a backup taken before the first save.": "Mở property list dưới dạng bảng khóa/kiểu/giá trị có thể chỉnh sửa, với bản sao lưu được tạo trước lần lưu đầu tiên.",
        "Optional label": "Nhãn tùy chọn",
        "Organization: %@": "Tổ chức: %@",
        "Original": "Gốc",
