        "PIN": "PIN",
        "Package": "Gói",
        "Package Builder": "Trình tạo gói",
        "Package Format": "Định dạng gói",
        "Packages you build or import are stored on this device, in WorkTweaks' own container. Tap a package to edit it. Deploy runs it through the same preview, resolve and backup flow as a picked package.": "Các gói bạn tạo hoặc nhập được lưu trên thiết bị này, trong container riêng của WorkTweaks. Chạm vào một gói để chỉnh sửa. Deploy chạy gói qua cùng quy trình xem trước, xác định đích và sao lưu như một gói đã chọn.",
        "Pair This iPhone": "Ghép nối iPhone này",
