        "Pairing file saved to the app.": "Đã lưu tệp ghép nối vào ứng dụng.",
        "Parsed from the .plist files in the ConfigurationProfiles directory. This page never installs or removes a profile.": "Được phân tích từ các tệp .plist trong thư mục ConfigurationProfiles. Trang này không bao giờ cài đặt hay xóa hồ sơ.",
        "Partial — some icons may still show. Hidden through the archive's suppressed identifiers.": "Một phần — một số biểu tượng vẫn có thể hiển thị. Được ẩn qua các định danh bị chặn trong kho lưu trữ.",
