        "Rebooting now might cause a bootloop. Try pressing 'Revert Tweaks'.": "Khởi động lại ngay có thể gây bootloop. Hãy thử nhấn 'Khôi phục tinh chỉnh'.",
        "Recent Requests": "Yêu cầu gần đây",
