        "Apply Status Bar": "Применить Status Bar",
        "Apply Tweaks": "Применить твики",
        "Apply custom card art to your Apple Wallet cards on-device. Scan for your cards, attach a skin image to each one, then flash.": "Применяйте пользовательское оформление карт Apple Wallet на устройстве. Отсканируйте свои карты, прикрепите изображение скина к каждой, затем выполните flash.",
        "Apply — read this first": "Применить — сначала прочитайте это",
        "Apply/Revert": "Применить/Отменить",
        "Applying…": "Применение…",
        "Apps": "Приложения",
        "Asset Tag": "Тег актива",
        "Back Up Now": "Сделать резервную копию",
        "Back Up as ZIP": "Сделать резервную копию как ZIP",
        "BackUP_Data folder, inside the WorkTweaks folder (Documents). You can browse it in the Files app.": "Папка BackUP_Data внутри папки WorkTweaks (Documents). Её можно просмотреть в приложении Files.",
        "BackUP_Data is empty.": "BackUP_Data пуста.",
        "Backing up…": "Создание резервной копии…",
        "Backup": "Резервная копия",
        "Backup Details": "Подробности резервной копии",
        "Backup Photos & Videos": "Резервное копирование фото и видео",
        "Backup Your Photos & Videos Here!": "Сделайте резервную копию фото и видео здесь!",
        "Backup and receipt saved under DeployBackups/%@ — restore it any time from Deploy History.": "Резервная копия и квитанция сохранены в DeployBackups/%@ — восстановите их в любое время из Deploy History.",
        "Bars: %d": "Деления: %d",
        "Battery": "Батарея",
        "Battery & Thermal": "Батарея и температура",
        "Battery & Thermal reads the system powerlog database: battery level, true health (raw max vs design capacity), cycle count, cell temperature, and thermal history. Values come from the latest samples in the log, newest first.": "«Battery & Thermal» читает системную базу данных powerlog: уровень заряда, истинное состояние здоровья (сырое максимальное значение против проектной ёмкости), число циклов, температуру элемента и историю нагрева. Значения берутся из последних записей журнала, сначала самые новые.",
        "Battery Percentage": "Процент заряда",
        "Before anything is written, every file that already exists is backed up (see Deploy History). Existing files are then replaced in place; new files are created.": "Прежде чем что-либо будет записано, каждый существующий файл сохраняется в резервную копию (см. Deploy History). Существующие файлы затем заменяются на месте; новые файлы создаются.",
        "Blocked — pairing / VPN not ready": "Заблокировано — pairing / VPN не готовы",
        "Both need a pairing file first: Sandbox → Utilities → Get Pairing File. A loopback VPN (Local Dev VPN) is strongly recommended while flashing.": "Обоим сначала нужен файл pairing: Sandbox → Utilities → Get Pairing File. Во время flashing настоятельно рекомендуется loopback-VPN (Local Dev VPN).",
        "Browse Files": "Просмотреть файлы",
        "Build": "Сборка",
        "Build & Install Wallpaper": "Создать и установить обои",
        "Building still wallpaper…": "Создание статичных обоев…",
        "Builds a PosterBoard wallpaper on-device from your photo or video — the same descriptor format as an imported .tendies package, installed and listed exactly like one.": "Создаёт обои PosterBoard на устройстве из вашего фото или видео — в том же формате дескрипторов, что и импортированный пакет .tendies, устанавливается и отображается точно так же.",
        "Built on the worse_query core system by ForceQuit OS, with CacheExtra key knowledge from mond by rooootdev (AGPL-3.0).": "Создано на основе основной системы worse_query от ForceQuit OS, со знанием ключей CacheExtra из mond от rooootdev (AGPL-3.0).",
        "Bundle ID": "Bundle ID",
        "Bundle ID to whitelist": "Bundle ID для белого списка",
        "By Key": "По ключу",
        "By Tweak": "По твику",
        "Byte": "Байт",
        "Cache": "Кэш",
        "Cache Data Cleaner": "Очистка данных кэша",
        "Cache Locations": "Расположения кэша",
        "Cache lives in two places inside an app's data container: Library/Caches and tmp. Only the contents of those two folders are deleted — the folders themselves stay, and Documents and the rest of Library are never touched.": "Кэш находится в двух местах внутри контейнера данных приложения: Library/Caches и tmp. Удаляется только содержимое этих двух папок — сами папки остаются, а Documents и остальная часть Library никогда не трогаются.",
        "Cancel": "Отмена",
        "Cancel Pairing": "Отменить pairing",
        "Card Hash": "Хэш карты",
        "Card name (optional)": "Название карты (необязательно)",
        "Cards (%d)": "Карты (%d)",
        "Carrier name (Primary)": "Название оператора (основная)",
        "Carrier name (Secondary)": "Название оператора (дополнительная)",
        "Carrier name (max 64)": "Название оператора (макс. 64)",
        "Cell temperature": "Температура элемента",
        "Certificate": "Сертификат",
        "Certificates tab: create your certificate if needed. A free team can hold only one active development certificate — if creation fails with error 7460, revoke an old unused certificate there first.": "Вкладка Certificates: при необходимости создайте сертификат. Бесплатная команда может иметь только один активный сертификат разработчика — если создание завершается ошибкой 7460, сначала отзовите старый неиспользуемый сертификат там.",
        "Change .passthm…": "Изменить .passthm…",
        "Change the carrier name, network label and signal bars. iOS 27 only. A separate system from the Tweaks tab. LiveContainer is not recommended for this — use a direct install (Signed Apps) instead.": "Измените название оператора, сетевую метку и деления сигнала. Только iOS 27. Отдельная система от вкладки Tweaks. LiveContainer для этого не рекомендуется — вместо этого используйте прямую установку (Signed Apps).",
        "Charging": "Зарядка",
        "Checking…": "Проверка…",
        "Choose .passthm from Files…": "Выбрать .passthm из Files…",
        "Choose Image Source": "Выбрать источник изображения",
        "Choose Key %@ Image Source": "Выбрать источник изображения для ключа %@",
