        "Choose another image or try downloading the photo to your iPhone first.": "Выберите другое изображение или сначала попробуйте скачать фото на свой iPhone.",
        "Choose from Files…": "Выбрать из Files…",
        "Choose the WorkTweaks IPA and install it.": "Выберите IPA WorkTweaks и установите его.",
