        "Clean up": "Очистить",
        "Cleaning is permanent — cache is not backed up. The app itself, its documents, and its settings are not affected.": "Очистка необратима — кэш не сохраняется в резервную копию. Само приложение, его документы и настройки не затрагиваются.",
