        "Configuration Profiles": "Профили конфигурации",
        "Connect your iPhone by USB, then sign in with your Apple ID in iLoader.": "Подключите iPhone по USB, затем войдите со своим Apple ID в iLoader.",
        "Connect your iPhone to power, connect to Wi-Fi, and leave the Settings → General → iPhone Storage tab open for about 1 hour while the model downloads.": "Подключите iPhone к питанию, подключитесь к Wi-Fi и оставьте открытой вкладку «Настройки» → «Основные» → «Хранилище iPhone» примерно на 1 час, пока скачивается модель.",
        "Connected%@": "Подключено%@",
