        "Containers (%d)": "Контейнеры (%d)",
        "Containers are enumerated with the fork's pathleak scan — the kernel refuses a grant on the container root itself, so there is no faster way to list them.": "Контейнеры перечисляются с помощью сканирования pathleak из форка — ядро отклоняет grant на сам корень контейнера, поэтому более быстрого способа их перечислить нет.",
