        "Developer": "Разработчик",
        "Developer of the web-based respring approach used by this app (via mond).": "Разработчик веб-подхода к respring, используемого этим приложением (через mond).",
        "Device Artwork": "Оформление устройства",
        "Device Configuration": "Конфигурация устройства",
        "Device Name": "Имя устройства",
