        "Lock": "Заблокировать",
        "Lock All": "Заблокировать все",
        "Lock Screen Footnote": "Footnote экрана блокировки",
        "Lock Screen Footnote is unavailable": "Footnote экрана блокировки недоступна",
        "Lock Screen Preview": "Предпросмотр экрана блокировки",
        "Locked folders are read-only (0555) with a sentinel file inside; config files are emptied and locked (0444). A Weak Lock is a locked folder missing its sentinel — tap Harden to add it.": "Заблокированные папки доступны только для чтения (0555) и содержат внутри файл-сторож; файлы конфигурации очищаются и блокируются (0444). Weak Lock — это заблокированная папка без файла-сторожа: нажмите Harden, чтобы добавить его.",
        "Locks every target below that still needs action. Whitelisted targets are always skipped.": "Блокирует все цели ниже, которые ещё требуют действий. Цели из белого списка всегда пропускаются.",
        "Log": "Журнал",
        "Loop (forwards and backwards)": "Цикл (вперёд и назад)",
        "Manifest": "Манифест",
        "Measuring cache…": "Измерение кэша…",
        "Measuring…": "Измерение…",
        "Media": "Медиа",
        "Menus": "Меню",
        "MobileGestalt is empty": "MobileGestalt пуст",
        "MobileGestalt loaded": "MobileGestalt загружен",
        "Mode": "Режим",
        "Model": "Модель",
        "My Packages": "Мои пакеты",
        "Name": "Имя",
        "Nested dictionaries, arrays and Data are shown read-only — the editor never rewrites a structure it cannot show.": "Вложенные словари, массивы и данные Data отображаются только для чтения — редактор никогда не переписывает структуру, которую не может показать.",
        "Network Type Label": "Метка типа сети",
        "Network label (Primary)": "Метка сети (основная)",
        "Network label (Secondary)": "Метка сети (дополнительная)",
        "Network type": "Тип сети",
        "Never share your certificate .p12 file with anyone — it contains your private signing key.": "Никогда не делитесь файлом сертификата .p12 ни с кем — в нём содержится ваш закрытый ключ подписи.",
        "New Package": "Новый пакет",
        "New Row": "Новая строка",
        "New UI": "Новый интерфейс",
        "No": "Нет",
        "No AI cache targets were found.": "Целей кэша ИИ не найдено.",
        "No Cards Detected Yet": "Карты пока не обнаружены",
        "No Jailbreak": "Без джейлбрейка",
        "No ad targets found yet. Tap Scan above.": "Целей рекламы пока не найдено. Нажмите «Сканировать» выше.",
        "No backed-up photos or videos yet. Use \"Backup Your Photos & Videos Here!\" first.": "Резервных копий фото или видео пока нет. Сначала используйте \"Backup Your Photos & Videos Here!\".",
        "No containers were found, so there is nothing to clean.": "Контейнеры не найдены, поэтому очищать нечего.",
        "No deploys yet. When a package is deployed, the files it replaced are backed up here with a receipt, ready to restore.": "Развёртываний пока нет. Когда пакет развёрнут, заменённые им файлы сохраняются здесь с квитанцией и готовы к восстановлению.",
        "No diagnostic reports found — nothing has been killed or crashed recently, or the reports were already cleaned.": "Диагностических отчётов не найдено — недавно ничего не завершалось и не падало, либо отчёты уже очищены.",
        "No files yet.": "Файлов пока нет.",
        "No installable profile records were found in this directory.": "В этом каталоге не найдено записей профилей, пригодных для установки.",
        "No pairing file saved yet.": "Файл pairing пока не сохранён.",
        "No pairing file yet. Pair this iPhone first in Sandbox → Utilities → Get Pairing File — scanning and flashing need it.": "Файла pairing пока нет. Сначала выполните pairing этого iPhone в Sandbox → Utilities → Get Pairing File — для сканирования и прошивки он нужен.",
        "No recordings were found in the Voice Memos database.": "В базе данных Voice Memos записей не найдено.",
        "No regular files found in this container.": "В этом контейнере обычных файлов не найдено.",
        "No scan yet. The scan starts automatically; if it does not, open App Data once, or type the bundle ID by hand.": "Сканирования пока нет. Сканирование запускается автоматически; если этого не произошло, откройте App Data один раз или введите bundle ID вручную.",
        "No skin — tap Set Skin below": "Нет скина — нажмите Set Skin ниже",
        "No snapshots yet. Apply some tweaks or tap Back Up Now.": "Снимков пока нет. Примените несколько твиков или нажмите Back Up Now.",
        "No stored packages yet. Build one with New Package, or import an existing .deploy / .zip / folder package to edit it here.": "Сохранённых пакетов пока нет. Создайте один через New Package или импортируйте существующий пакет .deploy / .zip / папку, чтобы редактировать его здесь.",
        "No thermal events found in the powerlog.": "В powerlog тепловых событий не найдено.",
        "No third-party apps found.": "Сторонних приложений не найдено.",
        "No tweaks match \"%@\".": "Нет твиков, подходящих под \"%@\".",
        "No wallpapers imported yet. Wallpapers imported here are listed so you can remove them again — wallpapers added any other way are never touched.": "Импортированных обоев пока нет. Импортированные здесь обои перечислены, чтобы вы могли снова удалить их — обои, добавленные любым другим способом, никогда не трогаются.",
        "Nominal capacity": "Номинальная ёмкость",
        "Not Supervised": "Не под супервизией",
        "Not connected.": "Не подключено.",
        "Not loaded": "Не загружено",
        "Not measured yet": "Ещё не измерено",
        "Not present in this app": "Нет в этом приложении",
        "Not present in this backup": "Нет в этой резервной копии",
        "Not set": "Не задано",
        "Nothing applied yet.": "Пока ничего не применено.",
        "Nothing staged yet.": "Пока ничего не подготовлено.",
        "Nothing was written — the stored manifest is unchanged.": "Ничего не записано — сохранённый манифест не изменился.",
        "Nothing was written.": "Ничего не записано.",
        "Notice": "Уведомление",
        "Numbers only.": "Только цифры.",
        "OK": "OK",
        "Off": "Выкл",
        "Off in this backup": "Выкл в этой резервной копии",
        "Old UI": "Старый интерфейс",
        "On": "Вкл",
        "On a computer, download iLoader from iloader.app — the official site only — and open it.": "На компьютере скачайте iLoader с сайта iloader.app — только с официального сайта — и откройте его.",
        "On in this backup": "Вкл в этой резервной копии",
        "One of the destination paths is invalid.": "Один из путей назначения недействителен.",
        "Only files under Library/Caches inside the listed targets are deleted. AI models are never touched, and caches regenerate when the apps run again.": "Удаляются только файлы в Library/Caches внутри перечисленных целей. Модели ИИ никогда не трогаются, а кэши пересоздаются при следующем запуске приложений.",
        "Only spoof your device model if you want to download Apple Intelligence. This may break Face ID. If you decide to unspoof and want to keep Apple Intelligence, do NOT re-enter the Apple Intelligence & Siri menu in Settings.": "Подменяйте модель устройства только если хотите скачать Apple Intelligence. Это может сломать Face ID. Если решите отменить подмену и хотите сохранить Apple Intelligence, НЕ заходите снова в меню Apple Intelligence и Siri в Настройках.",
        "Only the listed .ips / .crash / .panic files under DiagnosticReports (and Retired) are ever deleted. The folders themselves are kept, and nothing else is touched.": "Удаляются только перечисленные файлы .ips / .crash / .panic в DiagnosticReports (и Retired). Сами папки сохраняются, и больше ничего не трогается.",
        "Open App Data first so the container scan runs, then come back — or tap Rescan.": "Сначала откройте App Data, чтобы запустилось сканирование контейнеров, затем вернитесь — или нажмите Rescan.",
        "Open Settings → Apple Intelligence & Siri and tap Join Waitlist. Wait about 15 minutes for it to be accepted.": "Откройте Settings → Apple Intelligence & Siri и нажмите Join Waitlist. Подождите около 15 минут, пока заявка будет принята.",
        "Open Signed Apps and sign in with your Apple ID.": "Откройте Signed Apps и войдите с вашим Apple ID.",
        "Open Source": "Открытый исходный код",
        "Open Tutorials": "Открыть руководства",
        "Open WorkTweaks and you're done.": "Откройте WorkTweaks — и готово.",
        "Open as Property List": "Открыть как Property List",
        "Open as SQLite Database": "Открыть как базу данных SQLite",
        "Open the Local Dev VPN app and connect. The tunnel shows as a utun interface on 10.7.x.x (gateway 10.7.0.1).": "Откройте приложение Local Dev VPN и подключитесь. Туннель отображается как интерфейс utun на 10.7.x.x (шлюз 10.7.0.1).",
        "Opening the configuration profiles…": "Открытие профилей конфигурации…",
        "Opening the database…": "Открытие базы данных…",
        "Opens an empty editor; the file is created when you save.": "Открывает пустой редактор; файл создаётся при сохранении.",
        "Opens the database as editable tables, with a backup taken before the first save. Close the owning app before editing.": "Открывает базу данных в виде редактируемых таблиц, с резервной копией перед первым сохранением. Перед редактированием закройте приложение-владелец.",
        "Opens the property list as an editable key/type/value table, with a backup taken before the first save.": "Открывает property list в виде редактируемой таблицы ключ/тип/значение, с резервной копией перед первым сохранением.",
        "Optional label": "Необязательная метка",
        "Organization: %@": "Организация: %@",
        "Original": "Оригинал",
        "Original (%d)": "Оригинал (%d)",
        "PIN": "PIN",
        "Package": "Пакет",
        "Package Builder": "Package Builder",
        "Package Format": "Формат пакета",
        "Packages you build or import are stored on this device, in WorkTweaks' own container. Tap a package to edit it. Deploy runs it through the same preview, resolve and backup flow as a picked package.": "Пакеты, которые вы создаёте или импортируете, хранятся на этом устройстве, в собственном контейнере WorkTweaks. Нажмите на пакет, чтобы редактировать его. Deploy выполняет его через тот же процесс предпросмотра, разрешения и резервного копирования, что и выбранный пакет.",
        "Pair This iPhone": "Выполнить pairing этого iPhone",
        "Pairing & Airlift": "Pairing и Airlift",
        "Pairing cancelled.": "Pairing отменён.",
        "Pairing file": "Файл pairing",
        "Pairing file imported.": "Файл pairing импортирован.",
        "Pairing file removed.": "Файл pairing удалён.",
        "Pairing file saved to the app.": "Файл pairing сохранён в приложении.",
        "Parsed from the .plist files in the ConfigurationProfiles directory. This page never installs or removes a profile.": "Разобрано из файлов .plist в каталоге ConfigurationProfiles. Эта страница никогда не устанавливает и не удаляет профили.",
        "Partial — some icons may still show. Hidden through the archive's suppressed identifiers.": "Частично — некоторые значки могут остаться. Скрыто через suppressed identifiers архива.",
        "Partially Supported": "Частично поддерживается",
        "Partially Supported iOS • %@": "Частично поддерживаемая iOS • %@",
        "Passcode Theme": "Тема passcode",
        "Passcode Themes": "Темы passcode",
        "Passcode theme applied": "Тема passcode применена",
        "Paste card hash": "Вставить хэш карты",
        "Path Enumeration": "Перечисление путей",
        "Paths must be relative, non-empty and contain no \"..\" component.": "Пути должны быть относительными, непустыми и не содержать компонента \"..\".",
        "Payload files are copied into the package. Add File accepts any file — a .plist is added as a payload, and a .zip is unpacked, each file inside becoming a payload with its destination defaulting to its path inside the archive. Destinations are relative paths only; absolute paths and \"..\" are rejected, exactly like an imported package.": "Файлы payload копируются в пакет. Add File принимает любой файл: .plist добавляется как payload, а .zip распаковывается — каждый файл внутри становится payload, а его назначение по умолчанию — его путь внутри архива. Назначения — только относительные пути; абсолютные пути и \"..\" отклоняются, точно как в импортированном пакете.",
        "Persist after reboot": "Сохранять после перезагрузки",
        "Photo Library": "Фототека",
        "Photo chosen — tap to change": "Фото выбрано — нажмите, чтобы изменить",
        "Photos & Videos": "Фото и видео",
        "Pick Target App": "Выбрать целевое приложение",
        "Pick an app": "Выбрать приложение",
        "Pick an app to see its cache and clean it.": "Выберите приложение, чтобы увидеть его кэш и очистить его.",
        "Pick from App Data scan…": "Выбрать из сканирования App Data…",
        "Pick the WorkTweaks IPA, set the Signing Bundle ID field to the same identifier, then tap Sign IPA.": "Выберите IPA WorkTweaks, установите поле Signing Bundle ID на тот же идентификатор, затем нажмите Sign IPA.",
        "Pick the photos and videos you want to keep, then Save. They are copied into the BackUP_Data folder inside the app. Optional — you can skip this.": "Выберите фото и видео, которые хотите сохранить, затем Save. Они копируются в папку BackUP_Data внутри приложения. Необязательно — можно пропустить.",
        "Plays a soft sound when you tap menus and features. Respects the silent switch.": "Воспроизводит тихий звук при нажатии на меню и функции. Учитывает переключатель беззвучного режима.",
        "Please Install It the Right Way": "Пожалуйста, установите правильным способом",
        "PosterBoard Data": "Данные PosterBoard",
        "PosterBoard Updated": "PosterBoard обновлён",
        "PosterBoard is unavailable": "PosterBoard недоступен",
        "Power": "Питание",
        "Prepare Share": "Подготовить отправку",
        "Preparing the container scan…": "Подготовка сканирования контейнеров…",
        "Preview (first 128 KB)": "Предпросмотр (первые 128 КБ)",
        "Probe Again": "Проверить снова",
        "Probing cache sizes…": "Проверка размеров кэша…",
        "Raw max capacity": "Сырая максимальная ёмкость",
        "Read": "Читать",
        "Read Powerlog": "Читать Powerlog",
        "Read complete%@%@.": "Чтение завершено%@%@.",
        "Read-only mode — the grant did not include write access, so Clean All is disabled.": "Режим только для чтения — предоставленный доступ не включал запись, поэтому Clean All отключён.",
        "Read-only: the powerlog is cloned into this app's temp folder and inspected there. Nothing is ever written to the system database. Some iOS 26 firmware restricts the powerlog sandbox token; iOS 27 reads fully.": "Только для чтения: powerlog копируется во временную папку этого приложения и проверяется там. В системную базу данных ничего никогда не записывается. Некоторые прошивки iOS 26 ограничивают токен песочницы powerlog; iOS 27 читает полностью.",
        "Reading the configuration profiles…": "Чтение профилей конфигурации…",
        "Reading the property list…": "Чтение property list…",
        "Reading the recordings database…": "Чтение базы данных записей…",
        "Reading video frames…": "Чтение кадров видео…",
        "Reading…": "Чтение…",
        "Rebooting now might cause a bootloop. Try pressing 'Revert Tweaks'.": "Перезагрузка сейчас может вызвать bootloop. Попробуйте нажать 'Revert Tweaks'.",
        "Recent Requests": "Недавние запросы",
        "Recent samples (%d)": "Недавние образцы (%d)",
        "Reference": "Справка",
        "Reference — APFS save-vault idea (clonefile staging, atomic swap with rollback).": "Справка — идея APFS save-vault (подготовка через clonefile, атомарная замена с откатом).",
        "Reference — PosterBoard wallpaper format the maker was verified against.": "Справка — формат обоев PosterBoard, по которому проверялся maker.",
        "Reference — Splash Ad Cache Lock mechanism (ad SDK cache lock, save vault, diagnostics, Wi-Fi file sharing, Voice Memos export, AI cache probes).": "Справка — механизм Splash Ad Cache Lock (блокировка кэша рекламных SDK, save vault, диагностика, обмен файлами по Wi-Fi, экспорт Voice Memos, пробы кэша ИИ).",
        "Reference — app-data browsing and portable patches": "Справка — просмотр app-data и портативные патчи",
        "Reference — cache data cleaner": "Справка — очистка данных кэша",
        "Reference — turn on new Siri AI (CacheData line edit + device spoof)": "Справка — включение нового Siri AI (правка строки CacheData + подмена устройства)",
        "Reference — video-to-wallpaper (CAML) builder used by the PosterBoard wallpaper maker.": "Справка — конструктор видео-в-обои (CAML), используемый maker'ом обоев PosterBoard.",
        "Refresh": "Обновить",
        "Refresh Status": "Обновить статус",
        "Region suffix (e.g. PA/A)": "Суффикс региона (например, PA/A)",
        "Release": "Освободить",
        "Release Sandbox Extension": "Освободить расширение Sandbox",
        "Remove": "Удалить",
        "Remove / Unload Theme": "Удалить / выгрузить тему",
        "Remove Footnote": "Удалить сноску",
        "Remove Pairing File": "Удалить файл сопряжения",
        "Report": "Отчёт",
        "Reports": "Отчёты",
        "Reports (%d)": "Отчёты (%d)",
        "Requires iOS %.1f+": "Требуется iOS %.1f+",
        "Rescan": "Сканировать повторно",
        "Reset": "Сбросить",
        "Resolve Target": "Определить цель",
        "Resolving the target container…": "Определение целевого контейнера…",
        "Respring": "Respring",
        "Respring did not trigger on this device.": "Respring не сработал на этом устройстве.",
        "Restart Device": "Перезагрузить устройство",
        "Restart Required": "Требуется перезагрузка",
        "Restore": "Восстановить",
        "Restore (%d)": "Восстановить (%d)",
        "Restore Backup": "Восстановить резервную копию",
        "Restore Everything": "Восстановить всё",
        "Restore Result — %d succeeded, %d failed": "Результат восстановления — успешно: %d, неудачно: %d",
        "Restore a ZIP backup": "Восстановить ZIP-копию",
        "Restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "Изменения после восстановления вступают в силу только после полной перезагрузки устройства — одного respring недостаточно. Выбор «Позже» лишь откладывает перезагрузку; изменения останутся ожидающими до перезагрузки.",
        "Restore into…": "Восстановить в…",
        "Restore swaps the staged copy into the app's current container and rolls back if anything fails. Release a snapshot only after you verified the restore in the app.": "Восстановление подменяет подготовленную копию на текущий контейнер приложения и откатывает изменения при любой ошибке. Освобождайте снимок только после того, как проверили восстановление в приложении.",
        "Restore the backup?": "Восстановить резервную копию?",
        "Restore this entire backup?": "Восстановить всю эту резервную копию?",
        "Restoring ZIP…": "Восстановление ZIP…",
        "Restoring the backup failed — the details are in the Log.": "Не удалось восстановить резервную копию — подробности в Log.",
        "Restoring writes each backed-up file back in place. Files the deploy created (they did not exist before) are deleted again.": "При восстановлении каждый файл из копии записывается обратно на своё место. Файлы, созданные при развёртывании (которых раньше не было), удаляются снова.",
        "Restoring…": "Восстановление…",
        "Result — %d succeeded, %d failed": "Результат — успешно: %d, неудачно: %d",
        "Retry Flash": "Повторить Flash",
        "Retry Flash Theme": "Повторить Flash темы",
        "Revert": "Отменить",
        "Revert Tweaks": "Отменить твики",
        "Revert all tweaks?": "Отменить все твики?",
        "Revert and restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "Изменения после отмены и восстановления вступают в силу только после полной перезагрузки устройства — одного respring недостаточно. Выбор «Позже» лишь откладывает перезагрузку; изменения останутся ожидающими до перезагрузки.",
        "Rewrites the entire MobileGestalt.plist from this backup. A device restart is required after restoring.": "Полностью перезаписывает MobileGestalt.plist из этой резервной копии. После восстановления требуется перезагрузка устройства.",
        "Running": "Выполняется",
        "Sampled": "Замеры сняты",
        "Sandbox access denied": "Доступ Sandbox запрещён",
        "Sandbox extension is ready (directory grant held).": "Расширение Sandbox готово (разрешение на каталог удерживается).",
        "Save": "Сохранить",
        "Save .passthm": "Сохранить .passthm",
        "Save App Group ID": "Сохранить ID App Group",
        "Save Vault": "Save Vault",
        "Saved": "Сохранено",
        "Saved %d of %d to BackUP_Data.": "Сохранено %d из %d в BackUP_Data.",
        "Saved: %@": "Сохранено: %@",
        "Saves the package, then shares ONE .zip file — save it in Files. Deploy imports that zip and applies it without asking for locations.": "Сохраняет пакет, затем отправляет ОДИН файл .zip — сохраните его в Files. Deploy импортирует этот zip и применяет его, не спрашивая пути.",
        "Saving %d of %d (%d%%)": "Сохранение %d из %d (%d%%)",
        "Saving applies the edits to the database through SQLite, takes a backup of the original first, then writes the edited file back in place. Close the owning app before saving — a running app can overwrite your edits.": "При сохранении правки применяются к базе данных через SQLite, сначала создаётся резервная копия оригинала, затем отредактированный файл записывается обратно на место. Перед сохранением закройте приложение-владелец — запущенное приложение может перезаписать ваши правки.",
        "Saving rebuilds the property list from this table, takes a backup of the original first, then writes it back in place. Close the owning app before saving — a running app can overwrite your edits.": "При сохранении список свойств (property list) перестраивается из этой таблицы, сначала создаётся резервная копия оригинала, затем он записывается обратно на место. Перед сохранением закройте приложение-владелец — запущенное приложение может перезаписать ваши правки.",
        "Saving writes the file in place and verifies the result by re-reading it.": "При сохранении файл записывается на место, а результат проверяется повторным чтением.",
        "Saving writes the file in place, under the container's sandbox extension.": "При сохранении файл записывается на место в пределах расширения Sandbox контейнера.",
        "Saving…": "Сохранение…",
        "Scan": "Сканировать",
        "Scan Cards": "Сканировать карты",
        "Scan for Ad Targets": "Найти рекламные цели",
        "Scanning %@…": "Сканирование %@…",
        "Scanning…": "Сканирование…",
        "Scope": "Область",
        "Search": "Поиск",
        "Search tweaks": "Поиск твиков",
        "Secondary bars: %d": "Деления вторичной шкалы: %d",
        "Secondary carrier name (max 64)": "Имя вторичного оператора (макс. 64)",
        "Secondary network type": "Тип вторичной сети",
        "Sections": "Разделы",
        "Select All": "Выбрать все",
        "Select None": "Снять выбор",
        "Select at least one card and attach a skin image to it before flashing.": "Выберите хотя бы одну карту и прикрепите к ней изображение скина перед прошивкой.",
        "Selected app": "Выбранное приложение",
        "Server": "Сервер",
        "Set NULL": "Установить NULL",
        "Set Skin": "Установить скин",
        "Set Skin for All Cards…": "Установить скин для всех карт…",
        "Set the Spoofing picker (under Apple Intelligence) to iPhone 17 Pro (iPhone18,1).": "Установите в выборе Spoofing (в разделе Apple Intelligence) значение iPhone 17 Pro (iPhone18,1).",
        "Sets how many bars are drawn. Static — it does not follow the real signal.": "Задаёт, сколько делений отображается. Статично — не зависит от реального сигнала.",
        "Share %@": "Поделиться %@",
        "Share Contents": "Поделиться содержимым",
        "Share Full Report": "Поделиться полным отчётом",
        "Showing the first %@ of %@ rows — the editor is for targeted edits, not bulk dumps.": "Показаны первые %@ из %@ строк — редактор предназначен для точечных правок, а не для массовых выгрузок.",
        "Shows the battery percentage in the status bar. Key: SBShowBatteryPercentage in com.apple.springboard.plist.": "Показывает процент заряда в строке состояния. Ключ: SBShowBatteryPercentage в com.apple.springboard.plist.",
        "Sign In": "Войти",
        "Signal Bars": "Деления сигнала",
        "Signal bars (Primary)": "Деления сигнала (основные)",
        "Signal bars (Secondary)": "Деления сигнала (вторичные)",
        "Single-file shorthand: instead of \"files\", give \"relativePath\" and \"file\". \"scope\" is Application (bundleID = the app's bundle ID), AppGroup (bundleID = the group identifier, e.g. group.com.example) or InternalDaemon. ZIP archives may use stored or deflated entries; encrypted and ZIP64 archives are not supported. Older .deploy archives and plain folders still import.": "Краткая запись для одного файла: вместо «files» укажите «relativePath» и «file». «scope» — это Application (bundleID = bundle ID приложения), AppGroup (bundleID = идентификатор группы, например group.com.example) или InternalDaemon. ZIP-архивы могут содержать записи stored или deflated; зашифрованные архивы и ZIP64 не поддерживаются. Старые архивы .deploy и обычные папки по-прежнему импортируются.",
        "Size": "Размер",
        "Sizes are measured by walking each folder. An app recreates cache as it runs, so the size grows back over time.": "Размеры измеряются обходом каждой папки. Приложение пересоздаёт кэш во время работы, поэтому размер со временем снова растёт.",
        "Sizes are probed read-only (depth 4). Delete Cache removes only files under Library/Caches inside these targets — the AI models live elsewhere and are never touched.": "Размеры определяются только чтением (глубина 4). «Удалить кэш» удаляет только файлы в Library/Caches внутри этих целей — модели ИИ находятся в другом месте и никогда не затрагиваются.",
        "Snapshots": "Снимки",
        "Software-Oriented Features": "Программные функции",
        "Some tweaks — especially Apple Intelligence — only take effect after a full restart, not a respring.": "Некоторые твики — особенно Apple Intelligence — вступают в силу только после полной перезагрузки, а не после respring.",
        "Something went wrong": "Что-то пошло не так",
        "Sound Effects": "Звуковые эффекты",
        "Splash Ad Cache Lock": "Splash Ad Cache Lock",
        "Splash Ad Cache Lock finds the folders ad SDKs use to cache splash (launch) ads, empties them, and locks them read-only so the app cannot rebuild its splash-ad cache. Locks apply only to third-party app folders — never to system folders, Documents, or the app itself.": "Splash Ad Cache Lock находит папки, которые рекламные SDK используют для кэширования splash-рекламы (при запуске), очищает их и блокирует только для чтения, чтобы приложение не могло заново создать кэш splash-рекламы. Блокировка применяется только к папкам сторонних приложений — никогда к системным папкам, Documents или самому приложению.",
        "Spoofing": "Spoofing",
        "SpringBoard loads the wallpaper store when it starts — respring or restart to see the change in the wallpaper gallery.": "SpringBoard загружает хранилище обоев при запуске — сделайте respring или перезагрузку, чтобы увидеть изменение в галерее обоев.",
        "SpringBoard options — battery percentage and Dynamic Island. iOS 27 only. A separate system from the Tweaks tab. LiveContainer is not recommended for this — use a direct install (Signed Apps) instead.": "Параметры SpringBoard — процент заряда и Dynamic Island. Только iOS 27. Отдельная система, не связанная с вкладкой Tweaks. LiveContainer для этого не рекомендуется — используйте прямую установку (Signed Apps).",
        "SpringBoard reads the footnote when it starts — respring or restart to see it on the Lock Screen.": "SpringBoard читает сноску при запуске — сделайте respring или перезагрузку, чтобы увидеть её на экране блокировки.",
        "Stage an app's Documents, Library/Preferences and Library/Application Support (never Caches) before its 7-day certificate expires. After reinstall, the data is restored into the app's new container — matched by bundle id, not the old container UUID.": "Подготовьте Documents, Library/Preferences и Library/Application Support приложения (никогда Caches) до истечения 7-дневного сертификата. После переустановки данные восстанавливаются в новый контейнер приложения — по bundle id, а не по старому UUID контейнера.",
        "Stage copies into the APFS vault (no extra space). ZIP backup copies first, then zips — for very large apps use the APFS vault. Both refuse while the app is still writing its database.": "Подготовка копирует данные в APFS-хранилище (без дополнительного места). ZIP-копия сначала копирует, затем архивирует — для очень больших приложений используйте APFS-хранилище. Оба способа откажутся работать, пока приложение ещё записывает свою базу данных.",
        "Stage into APFS Vault": "Подготовить в APFS Vault",
        "Staged %@: %d file(s), %@. Verified against the source.": "Подготовлено %@: файлов: %d, %@. Сверено с источником.",
        "Staged snapshots": "Подготовленные снимки",
        "Staging…": "Подготовка…",
        "Start Server": "Запустить сервер",
        "Start Tweaks Feature": "Запустить функцию твиков",
        "Start the server to get its address.": "Запустите сервер, чтобы получить его адрес.",
        "Status Bar": "Строка состояния",
        "Still writing (%d active WAL file(s)) — close the app first": "Ещё идёт запись (активных WAL-файлов: %d) — сначала закройте приложение",
        "Stop Scan": "Остановить сканирование",
        "Stop Server": "Остановить сервер",
        "Stopped": "Остановлено",
        "Stored as text.": "Хранится как текст.",
        "Subtype": "Подтип",
        "Supervision": "Надзор",
        "Support": "Поддержка",
        "Supported": "Поддерживается",
        "Supported iOS Versions": "Поддерживаемые версии iOS",
        "Supported iOS • %@": "Поддерживаемые iOS • %@",
        "Swift implementation of the respring web view (via mond / jailbreak.party).": "Swift-реализация веб-представления respring (через mond / jailbreak.party).",
        "System": "Система",
        "System Caches": "Системный кэш",
        "System Language": "Язык системы",
        "Table": "Таблица",
        "Tap Read Powerlog to load the latest battery samples.": "Нажмите «Читать Powerlog», чтобы загрузить последние замеры батареи.",
        "Tap Refresh to list the diagnostic reports.": "Нажмите «Обновить», чтобы показать диагностические отчёты.",
        "Tap a key to assign a custom image.": "Нажмите на клавишу, чтобы назначить своё изображение.",
        "Target": "Цель",
        "Target Path": "Целевой путь",
        "Target container": "Целевой контейнер",
        "That file is not a pairing file.": "Этот файл — не файл сопряжения.",
        "The App Data scan is still running — ad targets appear once it finishes.": "Сканирование App Data ещё выполняется — рекламные цели появятся после его завершения.",
        "The CacheExtra key knowledge — the tweak-key research the WorkTweaks tweak catalog is built on.": "Знание ключей CacheExtra — исследование ключей твиков, на котором построен каталог твиков WorkTweaks.",
        "The Voice Memos container is found through the App Data scan.": "Контейнер Voice Memos находится через сканирование App Data.",
        "The ZIP must be a Save Vault backup (it carries a BackupManifest.plist). Files merge in place; system bundle ids are blocked.": "ZIP должен быть резервной копией Save Vault (в нём есть BackupManifest.plist). Файлы объединяются на месте; системные bundle id заблокированы.",
        "The backup of the original file couldn't be written, so nothing was saved.": "Не удалось записать резервную копию исходного файла, поэтому ничего не сохранено.",
        "The browser asks for these credentials once, then remembers them for the session.": "Браузер запросит эти учётные данные один раз, а затем запомнит их на время сессии.",
        "The bundle ID is not a valid identifier.": "Bundle ID — недопустимый идентификатор.",
        "The bundle ID of the one app this package may touch. Pick it from the App Data container scan, or type it.": "Bundle ID единственного приложения, которое может затрагивать этот пакет. Выберите его из сканирования контейнеров App Data или введите вручную.",
        "The container scan found no containers.": "Сканирование контейнеров не нашло ни одного контейнера.",
        "The container scan is shared with App Data and runs once per app session.": "Сканирование контейнеров общее с App Data и выполняется один раз за сессию приложения.",
        "The container scan runs once per session.": "Сканирование контейнеров выполняется один раз за сессию.",
        "The core system: the sandbox escape and MobileGestalt access this whole app is built on.": "Основная система: обход песочницы (sandbox escape) и доступ к MobileGestalt, на которых построено всё приложение.",
        "The current MobileGestalt will be entirely replaced with this %@ backup.": "Текущий MobileGestalt будет полностью заменён этой резервной копией %@.",
        "The current file is overwritten in place with the backup taken before the first byte edit.": "Текущий файл перезаписывается на месте копией, созданной до первой правки байтов.",
        "The developer's GitHub profile.": "Профиль разработчика на GitHub.",
        "The directory is empty.": "Каталог пуст.",
        "The entry is removed from the property list on the next Save.": "Запись будет удалена из списка свойств (property list) при следующем сохранении.",
        "The file couldn't be read under the container's sandbox extension — the details are in the Log. Nothing was written to it.": "Не удалось прочитать файл в пределах расширения Sandbox контейнера — подробности в Log. В него ничего не записывалось.",
        "The file-based CacheData pattern method used by Enable iPadOS Mode (MobileGestaltCacheDataTweak).": "Файловый метод шаблонов CacheData, используемый функцией Enable iPadOS Mode (MobileGestaltCacheDataTweak).",
        "The original identifiers are already registered to another developer account, which is why the Team ID suffix is required.": "Исходные идентификаторы уже зарегистрированы на другой аккаунт разработчика, поэтому требуется суффикс Team ID.",
        "The package could not be exported.": "Не удалось экспортировать пакет.",
        "The package store is unavailable (the App Group container did not resolve).": "Хранилище пакетов недоступно (контейнер App Group не определён).",
        "The pairing file + Local Dev VPN tunnel are the transport Airlift uses to reach the device. Green = ready, gray = not ready.": "Файл сопряжения и туннель Local Dev VPN — это транспорт, который Airlift использует для доступа к устройству. Зелёный = готово, серый = не готово.",
        "The pathleak scan reads inodes one by one — this can take a few minutes.": "Сканирование pathleak читает inode один за другим — это может занять несколько минут.",
        "The picked file could not be copied into the package.": "Не удалось скопировать выбранный файл в пакет.",
        "The row is deleted from the database on the next Save.": "Строка будет удалена из базы данных при следующем сохранении.",
        "The sandbox extension for this container's directory was refused — the result code is in the Log.": "Расширение Sandbox для каталога этого контейнера отклонено — код результата в Log.",
        "The scan of %@ found no containers. The scan's baseline and counts are in the Log.": "Сканирование %@ не нашло контейнеров. Исходные данные и счётчики сканирования — в Log.",
        "The server shares this app's Documents folder only — SaveVaultBackups, staged vaults and uploads. Nothing outside it is ever served. Keep this page open while transferring: the server stops when you leave the page or the app goes to the background.": "Сервер предоставляет только папку Documents этого приложения — SaveVaultBackups, подготовленные хранилища и загрузки. Ничего за её пределами никогда не отдаётся. Держите эту страницу открытой во время передачи: сервер останавливается, когда вы покидаете страницу или приложение уходит в фон.",
        "The staging vault lives in this app's Documents and does NOT survive uninstalling WorkTweaks. Verify a restore in the app first, then release the vault.": "Подготовленное хранилище находится в Documents этого приложения и НЕ переживёт удаление WorkTweaks. Сначала проверьте восстановление в приложении, затем освободите хранилище.",
        "The stored package is removed. Files it already deployed, and its Deploy History receipts, are not touched.": "Сохранённый пакет удалён. Файлы, которые он уже развернул, и квитанции истории Deploy не затрагиваются.",
        "Theme Information": "Информация о теме",
        "Thermal history (%d)": "История температуры (%d)",
        "These are the photos and videos in the BackUP_Data folder. Select the ones to restore, then Restore opens the share sheet — tap Save to Photos there.": "Это фото и видео в папке BackUP_Data. Выберите те, что нужно восстановить, затем «Восстановить» откроет меню отправки — нажмите там «Сохранить в Фото».",
        "This app is free software under the GNU AGPL v3 license, following the licenses of the projects above.": "Это приложение — свободное программное обеспечение по лицензии GNU AGPL v3, в соответствии с лицензиями перечисленных выше проектов.",
        "This app's own repository — issues and contributions welcome.": "Собственный репозиторий этого приложения — сообщения об ошибках и вклад приветствуются.",
        "This deletes only the listed .ips / .crash / .panic files. The folders are kept.": "Удаляются только перечисленные файлы .ips / .crash / .panic. Папки сохраняются.",
        "This device right now": "Это устройство сейчас",
        "This file isn't UTF-8 text, so it can't be edited as text. It can be edited byte-by-byte in the hex editor below.": "Этот файл — не текст в UTF-8, поэтому его нельзя редактировать как текст. Его можно редактировать побайтово в hex-редакторе ниже.",
        "This file isn't UTF-8 text, so it can't be edited here. Nothing is ever written to it from this page.": "Этот файл — не текст в UTF-8, поэтому его нельзя редактировать здесь. С этой страницы в него никогда ничего не записывается.",
        "This iOS Version Isn't Supported": "Эта версия iOS не поддерживается",
        "This is NOT an adblock: locking only stops ad assets landing on disk. Ads downloaded live over the network when the app opens can still appear.": "Это НЕ блокировщик рекламы: блокировка лишь не даёт рекламным ресурсам попасть на диск. Реклама, загружаемая по сети при открытии приложения, всё равно может появляться.",
        "This is the container's system-managed metadata file. iOS doesn't allow other processes to read its contents, so it can't be opened or edited here.": "Это системный файл метаданных контейнера. iOS не позволяет другим процессам читать его содержимое, поэтому его нельзя открыть или редактировать здесь.",
        "This only clears the list. It does not undo anything that was applied.": "Это лишь очищает список. Это не отменяет ничего из применённого.",
        "This only makes the Join Waitlist button appear. The Siri AI model may still refuse to download — that part is not solved by this method yet.": "Это лишь заставляет появиться кнопку Join Waitlist. Модель Siri AI всё ещё может отказаться загружаться — эта часть методом пока не решена.",
        "This package was rejected": "Этот пакет был отклонён",
        "This permanently deletes the contents of %@ in %@ (%@). The folders themselves stay in place.": "Это безвозвратно удаляет содержимое %@ в %@ (%@). Сами папки остаются на месте.",
        "This property list has no top-level entries.": "В этом списке свойств (property list) нет записей верхнего уровня.",
        "This removes the wallpaper imported from %@ — its descriptor folder is deleted from PosterBoard's data store.": "Это удаляет обои, импортированные из %@, — папка их дескриптора удаляется из хранилища данных PosterBoard.",
        "This restores the MobileGestalt backup saved on first launch (SavedGestalt.plist).": "Это восстанавливает резервную копию MobileGestalt, сохранённую при первом запуске (SavedGestalt.plist).",
        "This table has no columns to edit.": "В этой таблице нет столбцов для редактирования.",
        "Total CacheExtra keys": "Всего ключей CacheExtra",
        "True health": "Истинное здоровье",
        "Try Again": "Попробовать снова",
        "Turn on the Charge Limit Menu toggle (Add feature section).": "Включите переключатель Charge Limit Menu (раздел Add feature).",
        "Tutorials": "Обучение",
        "Tweaks": "Tweaks",
        "Tweaks Applied": "Твики применены",
        "Tweaks UI": "Интерфейс Tweaks",
        "Tweaks are locked": "Твики заблокированы",
        "Two ways to get a pairing file: Pair This iPhone (iOS 27 only) shows a 6-digit PIN — approve it in Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks. Or import a pairing file (.plist) from your computer manually. The pairing file is saved in the app.": "Два способа получить файл сопряжения: Pair This iPhone (только iOS 27) показывает 6-значный PIN — подтвердите его в «Настройки › Конфиденциальность и безопасность › Режим разработчика › Pair with WorkTweaks». Или импортируйте файл сопряжения (.plist) с компьютера вручную. Файл сопряжения сохраняется в приложении.",
        "Type": "Тип",
        "Type the region suffix as shown in Settings > General > About, e.g. PA/A or LL/A. It changes the Model Number suffix after Apply.": "Введите суффикс региона, как показано в «Настройки > Основные > Об этом устройстве», например PA/A или LL/A. После Apply он изменит суффикс номера модели.",
        "Type: %@ (%@). %@": "Тип: %@ (%@). %@",
        "Type: %@. %@": "Тип: %@. %@",
        "Universal mode flashes ~600 files for all languages & Bold text. Selecting a specific language (e.g. Ukrainian) speeds up flashing dramatically.": "Универсальный режим прошивает ~600 файлов для всех языков и жирного текста (Bold). Выбор конкретного языка (например, украинского) значительно ускоряет прошивку.",
        "Unknown time": "Неизвестное время",
        "Unlock": "Разблокировать",
        "Unlocks the Tweaks tab. Turn this on to start using tweaks.": "Разблокирует вкладку Tweaks. Включите это, чтобы начать пользоваться твиками.",
        "Unsupported": "Не поддерживается",
        "Unsupported iOS • %@": "Неподдерживаемая iOS • %@",
        "Use Skin": "Использовать скин",
        "Username": "Имя пользователя",
        "Utilities": "Утилиты",
        "VPN Tunnel": "VPN-туннель",
        "VPN tunnel is off. Open the Local Dev VPN app and connect — flashing needs it.": "VPN-туннель выключен. Откройте приложение Local Dev VPN и подключитесь — для прошивки он необходим.",
        "Valid until %@": "Действительно до %@",
        "Value": "Значение",
        "Value: %@": "Значение: %@",
        "Version %@": "Версия %@",
        "Video": "Видео",
        "Video chosen (%.1f s) — tap to change": "Видео выбрано (%.1f с) — нажмите, чтобы изменить",
        "Videos use the first 12 seconds. Photos become a single still frame.": "Видео используют первые 12 секунд. Фото становятся одним неподвижным кадром.",
        "View Full License & Credits": "Показать полную лицензию и кредиты",
        "Voice Memos": "Voice Memos",
        "Voice Memos & AI Cache": "Voice Memos и кэш ИИ",
        "Voltage": "Напряжение",
        "WARNING: These tweaks can break features on your device or softbrick it if misused. After Apply you choose Respring or Restart; Revert and Backup restores require a full device restart.": "ВНИМАНИЕ: эти твики могут сломать функции устройства или привести к softbrick при неправильном использовании. После Apply вы выбираете Respring или Restart; для отмены (Revert) и восстановления из копии требуется полная перезагрузка устройства.",
        "Waiting for the App Data scan…": "Ожидание сканирования App Data…",
        "Wallet Cards": "Карты Wallet",
        "Wallpaper": "Обои",
        "Wallpaper name": "Название обоев",
        "Warning": "Предупреждение",
        "Warning: raw byte edits have no structure validation — a wrong byte can corrupt this file or the owning app's data. A backup of the original is saved before the first edit.": "Предупреждение: правки необработанных байтов не проверяются на структуру — неверный байт может повредить этот файл или данные приложения-владельца. Резервная копия оригинала сохраняется перед первой правкой.",
        "WeChat accounts": "Аккаунты WeChat",
        "Welcome to WorkTweaks": "Добро пожаловать в WorkTweaks",
        "What this does": "Что это делает",
        "When enabled, MobileGestalt is written in-place on the same inode, which (hopefully) prevents iOS from regenerating the cache on reboot. Disable to use atomic file replacement instead.": "Когда включено, MobileGestalt записывается на месте, в тот же inode, что (как мы надеемся) не даёт iOS пересоздать кэш при перезагрузке. Отключите, чтобы вместо этого использовать атомарную замену файла.",
        "Where it goes": "Куда это попадёт",
        "Whitelist": "Whitelist",
        "Whitelisted": "В whitelist",
        "Whole numbers only.": "Только целые числа.",
        "Wi-Fi File Sharing": "Общий доступ к файлам по Wi-Fi",
        "WorkTweaks is free software under the GNU Affero General Public License v3.0. The core (worse_query) is GPL-3.0, but the CacheExtra key knowledge from mond and the CacheData method from Nugget are AGPL-3.0 — GPLv3 code may be combined into an AGPLv3 work, and the AGPL terms then cover the combined work as a whole.": "WorkTweaks — свободное программное обеспечение по лицензии GNU Affero General Public License v3.0. Ядро (worse_query) — GPL-3.0, но знание ключей CacheExtra от mond и метод CacheData от Nugget — AGPL-3.0; код GPLv3 может объединяться в произведение AGPLv3, и тогда условия AGPL распространяются на всё объединённое произведение в целом.",
        "WorkTweaks must be installed with iLoader, or by signing the IPA with Signed Apps, so that its App Group works correctly.": "WorkTweaks должен быть установлен через iLoader или путём подписи IPA с помощью Signed Apps, чтобы его App Group работала корректно.",
        "WorkTweaks only works when its App Group is part of the signing profile. Guides A and B make sure that happens — pick the one that fits you. Guide C turns on the new Siri AI.": "WorkTweaks работает только тогда, когда его App Group входит в профиль подписи. Руководства A и B обеспечивают это — выберите подходящее вам. Руководство C включает новый Siri AI.",
        "WorkTweaks v3.0 only opens on the builds listed above: the app checks your device's build at launch, and any other build gets the \"not supported\" screen instead of the app. On iOS 18 and iOS 26, only App Data and Airlift are supported (partial support). Developed and tested on iOS 27.0.1 (24A446).": "WorkTweaks v3.0 открывается только на сборках, перечисленных выше: при запуске приложение проверяет сборку вашего устройства, и любая другая сборка получит экран «not supported» вместо приложения. На iOS 18 и iOS 26 поддерживаются только App Data и Airlift (частичная поддержка). Разработано и протестировано на iOS 27.0.1 (24A446).",
        "Works on iOS 18.0 – 27.2 beta 2 (iOS 27.2 beta 3 and later patched the exploit).": "Работает на iOS 18.0 – 27.2 beta 2 (в iOS 27.2 beta 3 и новее эксплойт исправлен).",
        "Write Method": "Метод записи",
        "Write access available — Clean All can delete the listed reports.": "Доступ на запись есть — «Clean All» может удалить перечисленные отчёты.",
        "Writes SharedDeviceConfiguration.plist in place, keeping every other key in the file. SpringBoard reads the file when it starts, so a respring or restart is needed to see the change.": "Записывает SharedDeviceConfiguration.plist на месте, сохраняя все остальные ключи в файле. SpringBoard читает файл при запуске, поэтому для отображения изменения нужны respring или перезагрузка.",
        "Writing or verifying the file failed — the details are in the Log.": "Не удалось записать или проверить файл — подробности в Log.",
        "Writing the file failed — the details are in the Log.": "Не удалось записать файл — подробности в Log.",
        "Writing the footnote failed — the details are in the Log.": "Не удалось записать сноску — подробности в Log.",
        "Yes": "Да",
        "You can add multiple hashes at once — separate them with spaces, commas, or newlines.": "Можно добавить сразу несколько хэшей — разделяйте их пробелами, запятыми или переносами строк.",
        "Your All BackUP Files Here!": "Все ваши файлы BackUP здесь!",
        "Your device is running **%@**. WorkTweaks v2.0 only runs on the builds listed below, so the app can't open on this version.": "Ваше устройство работает на **%@**. WorkTweaks v2.0 работает только на сборках, перечисленных ниже, поэтому приложение не может открыться на этой версии.",
        "ZIP backup saved: %@. Share it to Files before you uninstall anything.": "ZIP-копия сохранена: %@. Отправьте её в Files, прежде чем что-либо удалять.",
        "empty": "пусто",
        "iOS Version": "Версия iOS",
        "iPadOS Features": "Функции iPadOS",
        "invalid": "недействительно",
        "the CacheExtra key knowledge behind the tweak catalog": "знание ключей CacheExtra, лежащее в основе каталога твиков",
        "the file-based CacheData method (iPadOS Mode)": "файловый метод CacheData (iPadOS Mode)",
        "the package": "пакет",
        "the respring technique (jailbreak.party)": "техника respring (jailbreak.party)",
        "true or false.": "true или false.",
        "v3.0 checks your device's build at launch and only opens on the supported builds. The full version & build list lives in License & Credits.": "v3.0 проверяет сборку вашего устройства при запуске и открывается только на поддерживаемых сборках. Полный список версий и сборок — в License & Credits.",
        "worse_query — the core system (sandbox escape)": "worse_query — основная система (sandbox escape)",
    ]
}
